```turtle
@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

ea: a owl:Ontology ;
    rdfs:label "Educational Assessment Ontology" ;
    rdfs:comment "Models classification claims about educational assessment made in the source corpus, including conflicting/overlapping classification schemes, which are intentionally preserved and flagged." .

#################################################################
# TOP-LEVEL CLASSES
#################################################################

ea:Assessment a owl:Class ;
    rdfs:label "Assessment" ;
    skos:altLabel "educational evaluation" ;
    rdfs:comment "Systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve student learning." .

ea:Examination a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Examination" ;
    skos:altLabel "test", "exam" ;
    rdfs:comment "An educational assessment intended to measure a test-taker's knowledge, skill, aptitude, physical fitness, or classification. Corpus: 'assessment is often used interchangeably with test but is not limited to tests' -- hence Examination is modeled as a subclass of Assessment, not identical to it." .

ea:Learning a owl:Class ; rdfs:label "Learning" .
ea:Feedback a owl:Class ; rdfs:label "Feedback" .
ea:Rubric a owl:Class ; rdfs:label "Rubric" ; skos:altLabel "scoring guide", "checklist" .
ea:GradingMethod a owl:Class ; rdfs:label "Grading Method" .
ea:TestItem a owl:Class ; rdfs:label "Test Item" ; skos:altLabel "question" .
ea:Validity a owl:Class ; rdfs:label "Validity" .
ea:Reliability a owl:Class ; rdfs:label "Reliability" .
ea:LearningOutcome a owl:Class ; rdfs:label "Learning Outcome" .
ea:LearningOutcomeTaxonomy a owl:Class ; rdfs:label "Learning Outcome Taxonomy" .
ea:TransferOfLearning a owl:Class ; rdfs:label "Transfer of Learning" .
ea:MeasurementTheory a owl:Class ; rdfs:label "Measurement Theory" .
ea:ProficiencyLevel a owl:Class ; rdfs:label "Proficiency Level" .
ea:TeacherEvaluationMethod a owl:Class ; rdfs:label "Teacher Evaluation Method" .
ea:AssessmentQualityIssue a owl:Class ; rdfs:label "Assessment Quality Issue" .
ea:CompetencyBasedLearning a owl:Class ;
    rdfs:label "Competency Based Learning" ;
    skos:altLabel "proficiency-based learning", "mastery-based learning", "outcome-based learning", "standards-based learning" ;
    rdfs:comment "Synonym 'performance-based' is also used by the corpus for this concept, overlapping confusingly with the distinct class ea:PerformanceBasedAssessment." .
ea:NormGroup a owl:Class ; rdfs:label "Norm Group" ; skos:altLabel "norming group" .
ea:AnswerOption a owl:Class ; rdfs:label "Answer Option" .
ea:Stem a owl:Class ; rdfs:label "Stem" .
ea:Criterion a owl:Class ; rdfs:label "Criterion" .
ea:AchievementLevel a owl:Class ; rdfs:label "Achievement Level" .
ea:Examiner a owl:Class ; rdfs:label "Examiner" .
ea:ExpertExaminer a owl:Class ; rdfs:subClassOf ea:Examiner .
ea:Candidate a owl:Class ; rdfs:label "Candidate" .

ea:Key a owl:Class ; rdfs:subClassOf ea:AnswerOption ; rdfs:label "Key" .
ea:Distractor a owl:Class ; rdfs:subClassOf ea:AnswerOption ; rdfs:label "Distractor" .
owl:AllDisjointClasses [ owl:members ( ea:Key ea:Distractor ) ] .

ea:CorrectiveFeedback a owl:Class ; rdfs:subClassOf ea:Feedback .
ea:Recast a owl:Class ; rdfs:subClassOf ea:CorrectiveFeedback .
ea:AnecdotalFeedback a owl:Class ; rdfs:subClassOf ea:CorrectiveFeedback .
ea:ScoreFeedback a owl:Class ; rdfs:subClassOf ea:CorrectiveFeedback .
owl:AllDisjointClasses [ owl:members ( ea:Recast ea:AnecdotalFeedback ea:ScoreFeedback ) ] .

#################################################################
# OBJECT / DATA PROPERTIES
#################################################################

ea:hasPurpose a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ; rdfs:range ea:PurposeCategory .
ea:hasGranularity a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ; rdfs:range ea:GranularityLevel .
ea:hasObjectivity a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ; rdfs:range ea:ObjectivityCategory .
ea:hasReferencing a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ; rdfs:range ea:ReferencingCategory .
ea:hasFormality a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ; rdfs:range ea:FormalityCategory .
ea:hasLocus a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ; rdfs:range ea:LocusCategory .
ea:hasAdministrationManner a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Examination ; rdfs:range ea:AdministrationManner .
ea:hasStakesLevel a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Examination ; rdfs:range ea:StakesLevel .
ea:hasTemporalOrientation a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ; rdfs:range ea:TemporalOrientation .
ea:hasPerformanceFormat a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ; rdfs:range ea:PerformanceFormatCategory .
ea:hasConstructValidityDirection a owl:ObjectProperty ;
    rdfs:domain ea:ConstructValidity ; rdfs:range ea:ConstructValidityDirection .
ea:hasCriterionTiming a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:CriterionValidity ; rdfs:range ea:CriterionTimingCategory .
ea:hasReliabilitySource a owl:ObjectProperty ;
    rdfs:domain ea:Reliability ; rdfs:range ea:ReliabilitySourceCategory .
ea:hasTransferDistance a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:TransferOfLearning ; rdfs:range ea:TransferDistanceCategory .
ea:hasTransferValence a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:TransferOfLearning ; rdfs:range ea:TransferValenceCategory .
ea:hasOption a owl:ObjectProperty ;
    rdfs:domain ea:TestItem ; rdfs:range ea:AnswerOption .
ea:hasStem a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:TestItem ; rdfs:range ea:Stem .
ea:hasRubric a owl:ObjectProperty ;
    rdfs:domain ea:Assessment ; rdfs:range ea:Rubric .
ea:hasNormGroup a owl:ObjectProperty ;
    rdfs:domain ea:Assessment ; rdfs:range ea:NormGroup .
ea:hasLearningOutcome a owl:ObjectProperty ;
    rdfs:domain ea:Assessment ; rdfs:range ea:LearningOutcome .
ea:hasItem a owl:ObjectProperty ;
    rdfs:domain ea:Examination ; rdfs:range ea:TestItem .
ea:isItemOf a owl:ObjectProperty ;
    owl:inverseOf ea:hasItem ; rdfs:domain ea:TestItem ; rdfs:range ea:Examination .
ea:hasFeedback a owl:ObjectProperty ;
    rdfs:domain ea:Assessment ; rdfs:range ea:Feedback .
ea:hasCriterion a owl:ObjectProperty ;
    rdfs:domain ea:Rubric ; rdfs:range ea:Criterion .
ea:hasAchievementLevel a owl:ObjectProperty ;
    rdfs:domain ea:Rubric ; rdfs:range ea:AchievementLevel .
ea:hasExaminer a owl:ObjectProperty ;
    rdfs:domain ea:Examination ; rdfs:range ea:Examiner .
ea:hasCandidate a owl:ObjectProperty ;
    rdfs:domain ea:Examination ; rdfs:range ea:Candidate .
ea:hasProficiencyLevel a owl:ObjectProperty ;
    rdfs:domain ea:CriterionReferencedAssessment ; rdfs:range ea:ProficiencyLevel .
ea:hasGradingMethod a owl:ObjectProperty ;
    rdfs:domain ea:Assessment ; rdfs:range ea:GradingMethod .

ea:hasReliabilityCoefficient a owl:DatatypeProperty ;
    rdfs:domain ea:Reliability ; rdfs:range xsd:decimal .
ea:hasCutScore a owl:DatatypeProperty ;
    rdfs:domain ea:CriterionReferencedAssessment ; rdfs:range xsd:decimal .
ea:hasItemCount a owl:DatatypeProperty ;
    rdfs:domain ea:Examination ; rdfs:range xsd:integer .

#################################################################
# AXIS: GRANULARITY
#################################################################

ea:GranularityLevel a owl:Class .
ea:IndividualLearnerLevel a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:LearningCommunityLevel a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:CourseLevel a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:AcademicProgramLevel a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:InstitutionLevel a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:EducationalSystemLevel a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:GranularityLevel owl:disjointUnionOf
    ( ea:IndividualLearnerLevel ea:LearningCommunityLevel ea:CourseLevel
      ea:AcademicProgramLevel ea:InstitutionLevel ea:EducationalSystemLevel ) .

#################################################################
# AXIS: PURPOSE (placement / formative / summative / diagnostic)
#################################################################

ea:PurposeCategory a owl:Class .
ea:PlacementPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:FormativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:SummativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:DiagnosticPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:PurposeCategory owl:disjointUnionOf
    ( ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose ) .

ea:PlacementAssessment a owl:Class ;
    rdfs:label "Placement Assessment" ;
    skos:altLabel "pre-assessment", "initial assessment", "threshold knowledge test", "TKT" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ] ) ] .

ea:FormativeAssessment a owl:Class ;
    rdfs:label "Formative Assessment" ;
    skos:altLabel "formative evaluation", "formative feedback", "assessment for learning",
                  "educative assessment", "classroom assessment" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ] ) ] .

ea:SummativeAssessment a owl:Class ;
    rdfs:label "Summative Assessment" ;
    skos:altLabel "summative evaluation", "assessment of learning" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ] ) ] .

ea:DiagnosticAssessment a owl:Class ;
    rdfs:label "Diagnostic Assessment" ;
    skos:altLabel "diagnostic testing" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ] ) ] ;
    rdfs:subClassOf ea:FormativeAssessment ;
    rdfs:comment "TENSION: one passage lists Placement/Formative/Summative/Diagnostic as four coordinate, mutually exclusive categories (modeled via the disjoint PurposeCategory partition), while another passage states 'A common form of formative assessment is diagnostic assessment', here modeled as rdfs:subClassOf ea:FormativeAssessment. Both axioms are kept, which makes ea:DiagnosticAssessment logically unsatisfiable -- this is intentional, documenting the corpus conflict rather than resolving it." .

#################################################################
# AXIS: OBJECTIVITY
#################################################################

ea:ObjectivityCategory a owl:Class .
ea:ObjectiveCategory a owl:Class ; rdfs:subClassOf ea:ObjectivityCategory .
ea:SubjectiveCategory a owl:Class ; rdfs:subClassOf ea:ObjectivityCategory .
ea:ObjectivityCategory owl:disjointUnionOf ( ea:ObjectiveCategory ea:SubjectiveCategory ) .

ea:ObjectiveAssessment a owl:Class ;
    rdfs:comment "A form of questioning that has a single correct answer." ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:ObjectiveCategory ] ) ] .

ea:SubjectiveAssessment a owl:Class ;
    rdfs:comment "A form of questioning that may have more than one correct answer." ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:SubjectiveCategory ] ) ] .

#################################################################
# AXIS: REFERENCING
#################################################################

ea:ReferencingCategory a owl:Class .
ea:CriterionReferencedCategory a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:NormReferencedCategory a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:IpsativeCategory a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:ReferencingCategory owl:disjointUnionOf
    ( ea:CriterionReferencedCategory ea:NormReferencedCategory ea:IpsativeCategory ) .

ea:CriterionReferencedAssessment a owl:Class ;
    skos:altLabel "standards-based assessment" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencedCategory ] ) ] .

ea:NormReferencedAssessment a owl:Class ;
    skos:altLabel "normative assessment" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencedCategory ] ) ] .

ea:IpsativeAssessment a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:IpsativeCategory ] ) ] .

ea:MasteryTest a owl:Class ;
    rdfs:subClassOf ea:CriterionReferencedAssessment ;
    owl:equivalentClass [ owl:intersectionOf ( ea:CriterionReferencedAssessment
        [ a owl:Restriction ; owl:onProperty ea:hasCutScore ; owl:someValuesFrom xsd:decimal ] ) ] ;
    rdfs:comment "Not all criterion-referenced tests have a cutscore; only those that do are mastery tests." .

ea:BelowBasicLevel a owl:Class ; rdfs:subClassOf ea:ProficiencyLevel .
ea:BasicLevel a owl:Class ; rdfs:subClassOf ea:ProficiencyLevel .
ea:ProficientLevel a owl:Class ; rdfs:subClassOf ea:ProficiencyLevel .
ea:AdvancedLevel a owl:Class ; rdfs:subClassOf ea:ProficiencyLevel .
ea:ProficiencyLevel owl:disjointUnionOf
    ( ea:BelowBasicLevel ea:BasicLevel ea:ProficientLevel ea:AdvancedLevel ) .

#################################################################
# AXIS: FORMALITY
#################################################################

ea:FormalityCategory a owl:Class .
ea:FormalCategory a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:InformalCategory a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:FormalityCategory owl:disjointUnionOf ( ea:FormalCategory ea:InformalCategory ) .

ea:FormalAssessment a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:FormalCategory ] ) ] .
ea:InformalAssessment a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:InformalCategory ] ) ] .

#################################################################
# AXIS: LOCUS (internal / external)
#################################################################

ea:LocusCategory a owl:Class .
ea:InternalLocus a owl:Class ; rdfs:subClassOf ea:LocusCategory .
ea:ExternalLocus a owl:Class ; rdfs:subClassOf ea:LocusCategory .
ea:LocusCategory owl:disjointUnionOf ( ea:InternalLocus ea:ExternalLocus ) .

ea:InternalAssessment a owl:Class ;
    rdfs:comment "Set and marked by the school (teachers)." ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasLocus ; owl:someValuesFrom ea:InternalLocus ] ) ] .
ea:ExternalAssessment a owl:Class ;
    rdfs:comment "Set by a governing body and marked by unbiased personnel." ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasLocus ; owl:someValuesFrom ea:ExternalLocus ] ) ] .

#################################################################
# AXIS: TEMPORAL ORIENTATION (backward-looking / forward-looking)
#################################################################

ea:TemporalOrientation a owl:Class .
ea:ForwardLookingOrientation a owl:Class ; rdfs:subClassOf ea:TemporalOrientation .
ea:BackwardLookingOrientation a owl:Class ; rdfs:subClassOf ea:TemporalOrientation .
ea:TemporalOrientation owl:disjointUnionOf ( ea:ForwardLookingOrientation ea:BackwardLookingOrientation ) .

ea:ForwardLookingAssessment a owl:Class ;
    rdfs:comment "Asks those being assessed to consider themselves in hypothetical future situations." ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasTemporalOrientation ; owl:someValuesFrom ea:ForwardLookingOrientation ] ) ] .

#################################################################
# PERFORMANCE-BASED ASSESSMENT + FORMAT AXIS
#################################################################

ea:PerformanceBasedAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
    rdfs:comment "Similar to summative assessment in that it focuses on achievement; a well-defined task requiring an extended response in a real-world application context." .

ea:PerformanceFormatCategory a owl:Class .
ea:ProductFormat a owl:Class ; rdfs:subClassOf ea:PerformanceFormatCategory .
ea:PerformanceEventFormat a owl:Class ; rdfs:subClassOf ea:PerformanceFormatCategory .
ea:PerformanceFormatCategory owl:disjointUnionOf ( ea:ProductFormat ea:PerformanceEventFormat ) .

ea:ProductAssessment a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( ea:PerformanceBasedAssessment
        [ a owl:Restriction ; owl:onProperty ea:hasPerformanceFormat ; owl:someValuesFrom ea:ProductFormat ] ) ] ;
    rdfs:comment "E.g. a painting, portfolio, paper, or exhibition." .
ea:PerformanceEventAssessment a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( ea:PerformanceBasedAssessment
        [ a owl:Restriction ; owl:onProperty ea:hasPerformanceFormat ; owl:someValuesFrom ea:PerformanceEventFormat ] ) ] ;
    rdfs:comment "E.g. a speech, athletic skill, musical recital, or reading." .

ea:AuthenticAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment, ea:PerformanceBasedAssessment ;
    skos:altLabel "performance assessment" ;
    rdfs:comment "Measurement of accomplishments within a realistic, practical context relevant outside school. TENSION: the Wikipedia-style passage treats AuthenticAssessment and PerformanceBasedAssessment as related-but-separate entries, while the Glossary of Education Reform states 'Performance assessments may also be called authentic assessments', i.e. full synonymy. Both the subclass link and the synonym altLabel are encoded." .

#################################################################
# STANDARDIZATION AXIS
#################################################################

ea:AdministrationManner a owl:Class .
ea:StandardAdministrationManner a owl:Class ; rdfs:subClassOf ea:AdministrationManner .
ea:NonStandardAdministrationManner a owl:Class ; rdfs:subClassOf ea:AdministrationManner .
ea:AdministrationManner owl:disjointUnionOf
    ( ea:StandardAdministrationManner ea:NonStandardAdministrationManner ) .

ea:StandardizedTest a owl:Class ;
    rdfs:comment "Administered and scored in a consistent or standard manner for all test takers." ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Examination
        [ a owl:Restriction ; owl:onProperty ea:hasAdministrationManner ; owl:someValuesFrom ea:StandardAdministrationManner ] ) ] .

ea:NonStandardizedTest a owl:Class ;
    rdfs:comment "Flexible in scope and format, and variable in difficulty." ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Examination
        [ a owl:Restriction ; owl:onProperty ea:hasAdministrationManner ; owl:someValuesFrom ea:NonStandardAdministrationManner ] ) ] .

ea:AchievementTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
    owl:equivalentClass [ owl:intersectionOf ( ea:StandardizedTest
        [ a owl:Restriction ; owl:onProperty ea:hasTemporalOrientation ; owl:someValuesFrom ea:BackwardLookingOrientation ] ) ] .
ea:AptitudeTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
    owl:equivalentClass [ owl:intersectionOf ( ea:StandardizedTest
        [ a owl:Restriction ; owl:onProperty ea:hasTemporalOrientation ; owl:someValuesFrom ea:ForwardLookingOrientation ] ) ] .
ea:CollegeAdmissionsTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:InternationalComparisonTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:PsychologicalTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
owl:AllDisjointClasses [ owl:members (
    ea:AchievementTest ea:AptitudeTest ea:CollegeAdmissionsTest
    ea:InternationalComparisonTest ea:PsychologicalTest ) ] .

#################################################################
# STAKES-LEVEL AXIS
#################################################################

ea:StakesLevel a owl:Class .
ea:HighStakesLevel a owl:Class ; rdfs:subClassOf ea:StakesLevel .
ea:LowStakesLevel a owl:Class ; rdfs:subClassOf ea:StakesLevel .
ea:StakesLevel owl:disjointUnionOf ( ea:HighStakesLevel ea:LowStakesLevel ) .

ea:HighStakesTest a owl:Class ;
    rdfs:comment "A test with a desired reward for good performance / important consequences for the test taker." ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Examination
        [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:HighStakesLevel ] ) ] .
ea:LowStakesTest a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Examination
        [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:LowStakesLevel ] ) ] .

ea:NormReferencedTest a owl:Class ;
    skos:altLabel "NRT" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Examination ea:NormReferencedAssessment ) ] .
ea:CriterionReferencedTest a owl:Class ;
    skos:altLabel "CRT" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Examination ea:CriterionReferencedAssessment ) ] .

ea:CompetitiveExamination a owl:Class ;
    rdfs:comment "Competitive exams are norm-referenced, high-stakes tests in which candidates are ranked." ;
    owl:equivalentClass [ owl:intersectionOf (
        ea:Examination
        [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencedCategory ]
        [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:HighStakesLevel ] ) ] .

#################################################################
# "Assessment types include" LIST -- explicitly NOT disjoint
# (corpus: "Most tests can be classified on multiple categories" /
#  "A single test can have multiple qualities")
#################################################################

ea:Quiz a owl:Class ; rdfs:subClassOf ea:Examination, ea:FormativeAssessment ;
    rdfs:comment "Instructors usually provide a quiz as a formative assessment." .
ea:MidtermExamination a owl:Class ; rdfs:subClassOf ea:Examination ;
    rdfs:subClassOf [ owl:unionOf ( ea:FormativeAssessment ea:SummativeAssessment ) ] ;
    rdfs:comment "A midterm exam is a type of formative OR summative assessment." .
ea:FinalExamination a owl:Class ; rdfs:subClassOf ea:Examination, ea:SummativeAssessment .
ea:PerformanceTest a owl:Class ; rdfs:subClassOf ea:Examination ;
    rdfs:comment "Requires an examinee to actually perform a task, e.g. a behind-the-wheel driving test; related to but separately named from ea:PerformanceBasedAssessment." ;
    rdfs:seeAlso ea:PerformanceBasedAssessment .

ea:ContinuousAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
    rdfs:comment "Evaluates a student's progress throughout a course; often includes formative assessment, used as an alternative to a final-examination system." .
ea:ComplexAssessment a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasRubric ; owl:someValuesFrom ea:Rubric ]
        [ a owl:Restriction ; owl:onProperty ea:hasExaminer ; owl:someValuesFrom ea:ExpertExaminer ] ) ] ;
    rdfs:comment "Requires a rubric and an expert examiner, e.g. thesis or funding-proposal assessment." .
ea:CommonAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
    rdfs:comment "Used across a school/department to promote consistent evaluation; may be formative or summative." .
ea:InterimAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
    rdfs:subClassOf ea:FormativeAssessment ;
    rdfs:subClassOf ea:SummativeAssessment ;
    rdfs:comment "TENSION: 'Some educators consider interim tests to be formative... but others consider them summative.' Both subClassOf axioms are encoded, which (given the disjointness of Formative/Summative) renders this class unsatisfiable by design." .
ea:ScreeningAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
    rdfs:comment "Used to determine whether students need specialized assistance/services or readiness for a program." .
ea:PreAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
    rdfs:comment "TENSION: one passage treats 'pre-assessment' as a synonym of ea:PlacementAssessment ('Placement evaluation, also referred to as pre-assessment...'), while the Glossary of Education Reform lists 'Pre-assessments' and 'Placement assessments' as two separate, distinctly defined bullet items. Modeled as a distinct class, closely related to ea:PlacementAssessment." ;
    rdfs:seeAlso ea:PlacementAssessment .

#################################################################
# TEST ITEM TAXONOMY
#################################################################

ea:ObjectiveQuestionItem a owl:Class ; rdfs:subClassOf ea:TestItem .
ea:SubjectiveQuestionItem a owl:Class ; rdfs:subClassOf ea:TestItem .
ea:FillInTheBlankItem a owl:Class ; rdfs:subClassOf ea:TestItem .
ea:MathematicsQuestionItem a owl:Class ; rdfs:subClassOf ea:TestItem ;
    rdfs:comment "Most mathematics questions employ a style that does not fall into the multiple-choice/fill-in-blank/essay categories." .
ea:TestItem owl:disjointUnionOf
    ( ea:ObjectiveQuestionItem ea:SubjectiveQuestionItem ea:FillInTheBlankItem ea:MathematicsQuestionItem ) .

ea:TrueFalseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveQuestionItem .
ea:MultipleChoiceItem a owl:Class ; rdfs:subClassOf ea:ObjectiveQuestionItem ;
    skos:altLabel "MCQ", "objective response" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
        [ a owl:Restriction ; owl:onProperty ea:hasOption ; owl:onClass ea:Key ;
          owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ] ) ] ;
    rdfs:comment "Only one answer may be keyed as correct." .
ea:MultipleResponseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveQuestionItem ;
    owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
        [ a owl:Restriction ; owl:onProperty ea:hasOption ; owl:onClass ea:Key ;
          owl:minQualifiedCardinality "2"^^xsd:nonNegativeInteger ] ) ] ;
    rdfs:comment "More than one answer may be keyed as correct." .
ea:MatchingItem a owl:Class ; rdfs:subClassOf ea:ObjectiveQuestionItem .
ea:ObjectiveQuestionItem owl:disjointUnionOf
    ( ea:TrueFalseItem ea:MultipleChoiceItem ea:MultipleResponseItem ea:MatchingItem ) .

ea:ExtendedResponseItem a owl:Class ; rdfs:subClassOf ea:SubjectiveQuestionItem .
ea:EssayItem a owl:Class ; rdfs:subClassOf ea:SubjectiveQuestionItem ;
    skos:altLabel "free response question", "FRQ", "essay question" .
ea:ShortAnswerItem a owl:Class ; rdfs:subClassOf ea:SubjectiveQuestionItem .
owl:AllDisjointClasses [ owl:members ( ea:ExtendedResponseItem ea:EssayItem ea:ShortAnswerItem ) ] .

#################################################################
# RELIABILITY
#################################################################

ea:ReliabilitySourceCategory a owl:Class .
ea:StudentRelatedReliabilitySource a owl:Class ; rdfs:subClassOf ea:ReliabilitySourceCategory .
ea:RaterRelatedReliabilitySource a owl:Class ; rdfs:subClassOf ea:ReliabilitySourceCategory .
ea:TestAdministrationRelatedReliabilitySource a owl:Class ; rdfs:subClassOf ea:ReliabilitySourceCategory .
ea:TestRelatedReliabilitySource a owl:Class ; rdfs:subClassOf ea:ReliabilitySourceCategory .
ea:ReliabilitySourceCategory owl:disjointUnionOf
    ( ea:StudentRelatedReliabilitySource ea:RaterRelatedReliabilitySource
      ea:TestAdministrationRelatedReliabilitySource ea:TestRelatedReliabilitySource ) .

ea:ReliabilityEstimationMethod a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:InterRaterReliability a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimationMethod .
ea:TestRetestReliability a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimationMethod ;
    skos:altLabel "temporal stability", "repeatability" .
ea:InterMethodReliability a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimationMethod ;
    skos:altLabel "parallel-forms reliability", "form equivalence" .
ea:InternalConsistencyReliability a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimationMethod .
ea:ReliabilityEstimationMethod owl:disjointUnionOf
    ( ea:InterRaterReliability ea:TestRetestReliability ea:InterMethodReliability ea:InternalConsistencyReliability ) .

ea:SplitHalfReliability a owl:Class ; rdfs:subClassOf ea:InterMethodReliability ;
    rdfs:comment "Treats the two halves of a measure as alternate forms, solving the practical difficulty of constructing true parallel forms." .

#################################################################
# VALIDITY
#################################################################

ea:ContentValidity a owl:Class ; rdfs:subClassOf ea:Validity ; skos:altLabel "logical validity" .
ea:CriterionValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:ConstructValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:FaceValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:ConsequentialValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:Validity owl:disjointUnionOf
    ( ea:ContentValidity ea:CriterionValidity ea:ConstructValidity ea:FaceValidity ea:ConsequentialValidity ) .

ea:ContentValidity rdfs:subClassOf ea:ConstructValidity .
ea:CriterionValidity rdfs:subClassOf ea:ConstructValidity .
ea:ConstructValidity rdfs:comment "TENSION: one passage lists Content/Criterion/Construct/Face/Consequential validity as five coordinate, disjoint categories of validity evidence. Another passage states 'Construct validity... subsumes all other types of validity' and 'Modern validity theory defines construct validity as the overarching concern of validity research, subsuming all other types of validity evidence'. Both the disjoint partition and the subsumption (rdfs:subClassOf ea:ConstructValidity on ea:ContentValidity and ea:CriterionValidity) are encoded, which is logically contradictory and is intentionally left unresolved." .

ea:CriterionTimingCategory a owl:Class .
ea:ConcurrentTiming a owl:Class ; rdfs:subClassOf ea:CriterionTimingCategory .
ea:PredictiveTiming a owl:Class ; rdfs:subClassOf ea:CriterionTimingCategory .
ea:CriterionTimingCategory owl:disjointUnionOf ( ea:ConcurrentTiming ea:PredictiveTiming ) .

ea:ConcurrentValidity a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( ea:CriterionValidity
        [ a owl:Restriction ; owl:onProperty ea:hasCriterionTiming ; owl:someValuesFrom ea:ConcurrentTiming ] ) ] .
ea:PredictiveValidity a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( ea:CriterionValidity
        [ a owl:Restriction ; owl:onProperty ea:hasCriterionTiming ; owl:someValuesFrom ea:PredictiveTiming ] ) ] .

ea:ConstructValidityDirection a owl:Class .
ea:ConvergentDirection a owl:Class ; rdfs:subClassOf ea:ConstructValidityDirection .
ea:DiscriminantDirection a owl:Class ; rdfs:subClassOf ea:ConstructValidityDirection .
ea:ConstructValidityDirection owl:disjointUnionOf ( ea:ConvergentDirection ea:DiscriminantDirection ) .

ea:ConvergentValidity a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( ea:ConstructValidity
        [ a owl:Restriction ; owl:onProperty ea:hasConstructValidityDirection ; owl:someValuesFrom ea:ConvergentDirection ] ) ] .
ea:DiscriminantValidity a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( ea:ConstructValidity
        [ a owl:Restriction ; owl:onProperty ea:hasConstructValidityDirection ; owl:someValuesFrom ea:DiscriminantDirection ] ) ] .

ea:SubjectMatterValidity a owl:Class ; rdfs:subClassOf ea:Validity ;
    owl:disjointWith ea:PredictiveValidity ;
    rdfs:comment "'Subject-matter validity', widely used in education, predicts the score a student would get on a similar test with different questions, contrasted by the corpus with 'predictive validity' used in the workplace to predict job performance." .

#################################################################
# RUBRIC AND GRADING METHOD
#################################################################

ea:HolisticRubric a owl:Class ; rdfs:subClassOf ea:Rubric .
ea:AnalyticRubric a owl:Class ; rdfs:subClassOf ea:Rubric .
ea:DevelopmentalRubric a owl:Class ; rdfs:subClassOf ea:Rubric .
owl:AllDisjointClasses [ owl:members ( ea:HolisticRubric ea:AnalyticRubric ea:DevelopmentalRubric ) ] .
ea:DevelopmentalRubric rdfs:subClassOf ea:AnalyticRubric ;
    rdfs:comment "TENSION: 'Rubrics can be classified as holistic, analytic, or developmental' (coordinate, disjoint list) vs 'Developmental rubrics, a subset of analytical rubrics' (subordinate). Both the disjointness and the subClassOf axiom are encoded, deliberately producing an unsatisfiable class." .

ea:HolisticGrading a owl:Class ; rdfs:subClassOf ea:GradingMethod ;
    skos:altLabel "holistic scoring", "nonreductionist grading" .
ea:AnalyticGrading a owl:Class ; rdfs:subClassOf ea:GradingMethod .
owl:AllDisjointClasses [ owl:members ( ea:HolisticGrading ea:AnalyticGrading ) ] .
ea:TraitInformedScoring a owl:Class ; rdfs:subClassOf ea:GradingMethod, ea:HolisticGrading ;
    rdfs:comment "Comes close to analytic scoring methods (scoring each trait independently) but 'remains holistic at heart', asking raters to take all traits into account before giving a single final score." .

#################################################################
# LEARNING OUTCOMES
#################################################################

ea:IntendedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ; skos:altLabel "aim" .
ea:MeasuredLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ; skos:altLabel "objective" .
ea:UnintendedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome .
ea:LearningOutcome owl:disjointUnionOf
    ( ea:IntendedLearningOutcome ea:MeasuredLearningOutcome ea:UnintendedLearningOutcome ) .

ea:BloomsTaxonomy a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy .
ea:StructureOfObservedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy ; skos:altLabel "SOLO" .
ea:DIKWPyramid a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy .
ea:ModelOfHierarchicalComplexity a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy .
ea:LearningOutcomeTaxonomy owl:disjointUnionOf
    ( ea:BloomsTaxonomy ea:StructureOfObservedLearningOutcome ea:DIKWPyramid ea:ModelOfHierarchicalComplexity ) .

#################################################################
# TRANSFER OF LEARNING
#################################################################

ea:TransferDistanceCategory a owl:Class .
ea:NearDistance a owl:Class ; rdfs:subClassOf ea:TransferDistanceCategory .
ea:FarDistance a owl:Class ; rdfs:subClassOf ea:TransferDistanceCategory .
ea:TransferDistanceCategory owl:disjointUnionOf ( ea:NearDistance ea:FarDistance ) .

ea:TransferValenceCategory a owl:Class .
ea:PositiveValence a owl:Class ; rdfs:subClassOf ea:TransferValenceCategory .
ea:NegativeValence a owl:Class ; rdfs:subClassOf ea:TransferValenceCategory .
ea:TransferValenceCategory owl:disjointUnionOf ( ea:PositiveValence ea:NegativeValence ) .

ea:NearTransfer a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( ea:TransferOfLearning
        [ a owl:Restriction ; owl:onProperty ea:hasTransferDistance ; owl:someValuesFrom ea:NearDistance ] ) ] .
ea:FarTransfer a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( ea:TransferOfLearning
        [ a owl:Restriction ; owl:onProperty ea:hasTransferDistance ; owl:someValuesFrom ea:FarDistance ] ) ] .
ea:PositiveTransfer a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( ea:TransferOfLearning
        [ a owl:Restriction ; owl:onProperty ea:hasTransferValence ; owl:someValuesFrom ea:PositiveValence ] ) ] .
ea:NegativeTransfer a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( ea:TransferOfLearning
        [ a owl:Restriction ; owl:onProperty ea:hasTransferValence ; owl:someValuesFrom ea:NegativeValence ] ) ] .

#################################################################
# LEARNING TYPE (formal / non-formal / informal)
#################################################################

ea:FormalLearning a owl:Class ; rdfs:subClassOf ea:Learning .
ea:NonFormalLearning a owl:Class ; rdfs:subClassOf ea:Learning .
ea:InformalLearning a owl:Class ; rdfs:subClassOf ea:Learning ;
    rdfs:comment "Informal learning is less structured than non-formal learning." .
ea:Learning owl:disjointUnionOf ( ea:FormalLearning ea:NonFormalLearning ea:InformalLearning ) .

#################################################################
# MEASUREMENT THEORY
#################################################################

ea:ClassicalTestTheory a owl:Class ; rdfs:subClassOf ea:MeasurementTheory .
ea:ItemResponseTheory a owl:Class ; rdfs:subClassOf ea:MeasurementTheory .
ea:RaschModel a owl:Class ; rdfs:subClassOf ea:MeasurementTheory .
owl:AllDisjointClasses [ owl:members ( ea:ClassicalTestTheory ea:ItemResponseTheory ea:RaschModel ) ] .

#################################################################
# TEACHER EVALUATION / QUALITY ISSUES
#################################################################

ea:ValueAddedMeasure a owl:Class ; rdfs:subClassOf ea:TeacherEvaluationMethod ; skos:altLabel "growth measure" .
ea:StudentGrowthMeasure a owl:Class ; rdfs:subClassOf ea:TeacherEvaluationMethod ;
    rdfs:comment "A related but distinct method from ea:ValueAddedMeasure; does not attempt to control for other influences on achievement." .

ea:ScoreInflation a owl:Class ; rdfs:subClassOf ea:AssessmentQualityIssue .
ea:MeasurementError a owl:Class ; rdfs:subClassOf ea:AssessmentQualityIssue .

#################################################################
# PORTFOLIO
#################################################################

ea:Portfolio a owl:Class ; rdfs:subClassOf ea:Assessment ; skos:altLabel "student portfolio" .
ea:DigitalPortfolio a owl:Class ; rdfs:subClassOf ea:Portfolio ; skos:altLabel "e-portfolio" .
ea:PhysicalPortfolio a owl:Class ; rdfs:subClassOf ea:Portfolio .
owl:AllDisjointClasses [ owl:members ( ea:DigitalPortfolio ea:PhysicalPortfolio ) ] .
ea:CapstonePortfolio a owl:Class ; rdfs:subClassOf ea:Portfolio ;
    rdfs:comment "Features work completed as part of a long-term, culminating project." .
