```turtle
@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

<http://example.org/onto/assessment> a owl:Ontology ;
  rdfs:comment "Ontology of educational assessment built strictly from the supplied corpus. Where the corpus presents conflicting classification schemes, both are encoded and the tension is documented in rdfs:comment annotations." .

#################################################################
# TOP-LEVEL CLASSES
#################################################################

ea:EvaluableItem a owl:Class ;
  rdfs:comment "Superclass covering anything the corpus describes as being objective or subjective (assessments and test items)." .

ea:Assessment a owl:Class ;
  rdfs:subClassOf ea:EvaluableItem ;
  rdfs:label "Assessment" ;
  skos:altLabel "educational evaluation" ;
  rdfs:comment "The systematic process of documenting and using empirical data on knowledge, skills, attitudes, aptitude and beliefs to refine programs and improve student learning." .

ea:Test a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "examination", "exam" ;
  rdfs:comment "An educational assessment intended to measure a test-taker's knowledge, skill, aptitude, physical fitness, or classification; 'assessment' is often used interchangeably with 'test' though assessment is broader." .

ea:TestItem a owl:Class ;
  rdfs:subClassOf ea:EvaluableItem ;
  skos:altLabel "item", "question" ;
  rdfs:comment "An individual element (stem/prompt plus expected response) of a test; the generic term 'item' is preferred over 'question' because not all items are phrased as questions." .

#################################################################
# GRANULARITY AXIS
#################################################################

ea:hasGranularity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:GranularityLevel .

ea:GranularityLevel a owl:Class ;
  owl:disjointUnionOf ( ea:LearnerGranularity ea:LearningCommunityGranularity
                         ea:CourseGranularity ea:ProgramGranularity
                         ea:InstitutionGranularity ea:EducationalSystemGranularity ) ;
  rdfs:comment "Assessment can focus on the individual learner, the learning community, a course, an academic program, the institution, or the educational system as a whole." .

ea:LearnerGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:LearningCommunityGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:CourseGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:ProgramGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:InstitutionGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:EducationalSystemGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .

#################################################################
# PURPOSE / TIMING AXIS  (placement, formative, summative, diagnostic)
#################################################################

ea:hasPurpose a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:PurposeCategory .

ea:PurposeCategory a owl:Class ;
  owl:disjointUnionOf ( ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose ) ;
  rdfs:comment "Assessment can be divided for convenience into placement, formative, summative and diagnostic categories." .

ea:PlacementPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:FormativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:SummativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:DiagnosticPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .

ea:PlacementAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ] ) ] ;
  skos:altLabel "pre-assessment", "initial assessment", "threshold knowledge test", "TKT" ;
  rdfs:comment "Used to place students according to prior achievement, level of knowledge or personal characteristics before instruction; establishes a baseline." .

ea:FormativeAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ] ) ] ;
  skos:altLabel "formative evaluation", "formative feedback", "educative assessment",
                "classroom assessment", "assessment for learning" ;
  rdfs:comment "Conducted during the learning process to modify teaching and learning activities; assessment FOR learning." .

ea:SummativeAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ] ) ] ;
  skos:altLabel "summative evaluation", "assessment of learning" ;
  rdfs:comment "Carried out at the end of a course or project to evaluate learning against a standard; assessment OF learning." .

ea:DiagnosticAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ] ) ] ;
  rdfs:subClassOf ea:FormativeAssessment ;
  rdfs:comment "TENSION: one passage lists diagnostic assessment as a fourth category coordinate with placement/formative/summative (hence modeled via the hasPurpose value-partition), while another passage states 'a common form of formative assessment is diagnostic assessment', which is modeled here as rdfs:subClassOf ea:FormativeAssessment. Both axioms are kept." .

ea:SelfAssessment a owl:Class ;
  rdfs:subClassOf ea:DiagnosticAssessment ;
  rdfs:comment "Self-assessment is a form of diagnostic assessment in which students assess themselves." .

ea:ForwardLookingAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Asks those being assessed to consider themselves in hypothetical future situations." .

ea:InterimAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Periodic/benchmark assessment used to track progress toward later tests. TENSION: the corpus notes some educators consider interim assessment formative while others consider it summative; no single subclass axiom is asserted." .

ea:ScreeningAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Used to determine whether students need specialized services or are ready to begin a course/program." .

#################################################################
# OBJECTIVE / SUBJECTIVE AXIS (applies to Assessments AND TestItems)
#################################################################

ea:hasEvaluationMode a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EvaluableItem ;
  rdfs:range ea:EvaluationModeCategory .

ea:EvaluationModeCategory a owl:Class ;
  owl:disjointUnionOf ( ea:ObjectiveMode ea:SubjectiveMode ) ;
  rdfs:comment "Assessment (and, separately, individual test items) is often categorized as either objective or subjective." .

ea:ObjectiveMode a owl:Class ; rdfs:subClassOf ea:EvaluationModeCategory .
ea:SubjectiveMode a owl:Class ; rdfs:subClassOf ea:EvaluationModeCategory .

ea:ObjectiveAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasEvaluationMode ; owl:someValuesFrom ea:ObjectiveMode ] ) ] ;
  rdfs:comment "A form of questioning that has a single correct answer." .

ea:SubjectiveAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasEvaluationMode ; owl:someValuesFrom ea:SubjectiveMode ] ) ] ;
  rdfs:comment "A form of questioning that may have more than one correct answer, or more than one way of expressing it." .

ea:ObjectiveQuestion a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
      [ a owl:Restriction ; owl:onProperty ea:hasEvaluationMode ; owl:someValuesFrom ea:ObjectiveMode ] ) ] ;
  rdfs:comment "Objective question types include true/false, multiple-choice, multiple-response, and matching." .

ea:SubjectiveQuestion a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
      [ a owl:Restriction ; owl:onProperty ea:hasEvaluationMode ; owl:someValuesFrom ea:SubjectiveMode ] ) ] ;
  rdfs:comment "Subjective questions include extended-response and essay questions." .

#################################################################
# REFERENCING AXIS (criterion / norm / ipsative)
#################################################################

ea:hasReferenceType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:ReferenceCategory .

ea:ReferenceCategory a owl:Class ;
  owl:disjointUnionOf ( ea:CriterionReference ea:NormReference ea:IpsativeReference ) ;
  rdfs:comment "Test results can be compared against an established criterion, against the performance of other students (norm), or against previous performance (ipsative)." .

ea:CriterionReference a owl:Class ; rdfs:subClassOf ea:ReferenceCategory .
ea:NormReference a owl:Class ; rdfs:subClassOf ea:ReferenceCategory .
ea:IpsativeReference a owl:Class ; rdfs:subClassOf ea:ReferenceCategory .

ea:CriterionReferencedAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:CriterionReference ] ) ] ;
  skos:altLabel "criterion-referenced test", "CRT", "standards-based assessment", "standards-referenced assessment" ;
  rdfs:comment "Candidates are measured against defined, objective criteria regardless of other examinees' scores; may use a cut-score." .

ea:NormReferencedAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:NormReference ] ) ] ;
  skos:altLabel "norm-referenced test", "NRT", "normative assessment", "grading on a curve" ;
  rdfs:comment "Yields an estimate of the position of the tested individual relative to a predefined population (norm group)." .

ea:IpsativeAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:IpsativeReference ] ) ] ;
  rdfs:comment "Self-comparison either in the same domain over time, or comparative to other domains within the same student." .

ea:hasCutScore a owl:DatatypeProperty ;
  rdfs:domain ea:CriterionReferencedAssessment ;
  rdfs:range xsd:decimal ;
  rdfs:comment "Minimum score required to pass a mastery/criterion-referenced test; not all criterion-referenced tests have one." .

#################################################################
# FORMAL / INFORMAL AXIS
#################################################################

ea:hasFormality a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:FormalityCategory .

ea:FormalityCategory a owl:Class ;
  owl:disjointUnionOf ( ea:FormalType ea:InformalType ) .

ea:FormalType a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:InformalType a owl:Class ; rdfs:subClassOf ea:FormalityCategory .

ea:FormalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:FormalType ] ) ] ;
  rdfs:comment "Usually implies a written document and is given a numerical score or grade." .

ea:InformalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:InformalType ] ) ] ;
  rdfs:comment "Occurs more casually and does not contribute to a student's final grade." .

#################################################################
# INTERNAL / EXTERNAL AXIS
#################################################################

ea:hasAdministrationScope a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:AdministrationScopeCategory .

ea:AdministrationScopeCategory a owl:Class ;
  owl:disjointUnionOf ( ea:InternalScope ea:ExternalScope ) .

ea:InternalScope a owl:Class ; rdfs:subClassOf ea:AdministrationScopeCategory .
ea:ExternalScope a owl:Class ; rdfs:subClassOf ea:AdministrationScopeCategory .

ea:InternalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasAdministrationScope ; owl:someValuesFrom ea:InternalScope ] ) ] ;
  rdfs:comment "Set and marked by the school (teachers)." .

ea:ExternalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasAdministrationScope ; owl:someValuesFrom ea:ExternalScope ] ) ] ;
  rdfs:comment "Set by a governing body and marked by unbiased personnel." .

#################################################################
# STANDARDIZATION AXIS
#################################################################

ea:hasStandardizationStatus a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:StandardizationCategory .

ea:StandardizationCategory a owl:Class ;
  owl:disjointUnionOf ( ea:StandardizedStatus ea:NonStandardizedStatus ) ;
  rdfs:comment "The opposite of standardized testing is non-standardized testing." .

ea:StandardizedStatus a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:NonStandardizedStatus a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .

ea:StandardizedTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStandardizationStatus ; owl:someValuesFrom ea:StandardizedStatus ] ) ] ;
  rdfs:comment "Administered and scored in a consistent/standard manner for all test takers." .

ea:NonStandardizedTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStandardizationStatus ; owl:someValuesFrom ea:NonStandardizedStatus ] ) ] ;
  rdfs:comment "Significantly different tests are given, or the same test is given under significantly different conditions or evaluated differently." .

ea:AchievementTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
  rdfs:comment "Measures knowledge/skills learned in school; 'backward-looking'." .
ea:AptitudeTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
  rdfs:comment "Attempts to predict ability to succeed in a future endeavor; 'forward-looking'." .
ea:CollegeAdmissionsTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:InternationalComparisonTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:PsychologicalTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .

owl:AllDisjointClasses [ owl:members ( ea:AchievementTest ea:AptitudeTest ea:CollegeAdmissionsTest
                                        ea:InternationalComparisonTest ea:PsychologicalTest ) ] .

#################################################################
# STAKES AXIS
#################################################################

ea:hasStakesLevel a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:StakesCategory .

ea:StakesCategory a owl:Class ;
  owl:disjointUnionOf ( ea:HighStakesLevel ea:LowStakesLevel ) .

ea:HighStakesLevel a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:LowStakesLevel a owl:Class ; rdfs:subClassOf ea:StakesCategory .

ea:HighStakesTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:HighStakesLevel ] ) ] ;
  rdfs:comment "A test with a desired reward for good performance, or important consequences for the test taker." .

ea:LowStakesTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:LowStakesLevel ] ) ] ;
  rdfs:comment "Carries no significant or public consequences, e.g. ordinary classroom quizzes." .

ea:CompetitiveExamination a owl:Class ;
  rdfs:subClassOf ea:Test ;
  owl:equivalentClass [ owl:intersectionOf ( ea:NormReferencedAssessment ea:HighStakesTest ) ] ;
  rdfs:comment "Norm-referenced, high-stakes tests in which candidates are ranked and top rankers selected (e.g. civil-service exams)." .

ea:MultipleQualitiesComment a owl:Class ;
  rdfs:comment "NOTE: the corpus explicitly states that most tests can be classified on multiple categories simultaneously (e.g. a test can be both standardized and high-stakes and multiple-choice). Therefore the axes above (purpose, reference, formality, scope, standardization, stakes, administration mode, evaluation mode) are modeled as independent, cross-cutting properties rather than as a single disjoint partition of Assessment/Test." .

#################################################################
# ADMINISTRATION MODE AXIS
#################################################################

ea:hasAdministrationMode a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:AdministrationModeCategory .

ea:AdministrationModeCategory a owl:Class ;
  owl:disjointUnionOf ( ea:VerbalMode ea:WrittenMode ea:ComputerMode ea:PracticalMode ) ;
  rdfs:comment "A test may be administered verbally, on paper, on a computer, or in a predetermined area requiring demonstration of skills." .

ea:VerbalMode a owl:Class ; rdfs:subClassOf ea:AdministrationModeCategory .
ea:WrittenMode a owl:Class ; rdfs:subClassOf ea:AdministrationModeCategory .
ea:ComputerMode a owl:Class ; rdfs:subClassOf ea:AdministrationModeCategory .
ea:PracticalMode a owl:Class ; rdfs:subClassOf ea:AdministrationModeCategory .

ea:WrittenTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasAdministrationMode ; owl:someValuesFrom ea:WrittenMode ] ) ] ;
  rdfs:comment "Administered on paper or computer, requiring written/typed responses." .

#################################################################
# PERFORMANCE / AUTHENTIC ASSESSMENT
#################################################################

ea:PerformanceAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasAdministrationMode ; owl:someValuesFrom ea:PracticalMode ] ) ] ;
  skos:altLabel "performance-based assessment", "performance test" ;
  rdfs:comment "Requires an examinee to actually perform a task or activity rather than simply answer questions; similar to summative assessment in focusing on achievement." .

ea:hasContext a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:ContextCategory .

ea:ContextCategory a owl:Class ;
  owl:disjointUnionOf ( ea:RealWorldContext ea:SchoolContext ) .

ea:RealWorldContext a owl:Class ; rdfs:subClassOf ea:ContextCategory .
ea:SchoolContext a owl:Class ; rdfs:subClassOf ea:ContextCategory .

ea:AuthenticAssessment a owl:Class ;
  rdfs:subClassOf ea:PerformanceAssessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasContext ; owl:someValuesFrom ea:RealWorldContext ] ) ] ;
  rdfs:comment "The measurement of accomplishments within a realistic, practical context relevant outside the school setting; corpus states performance assessments 'may also be called' authentic assessments." .

ea:hasOutcomeForm a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:PerformanceAssessment ;
  rdfs:range ea:OutcomeFormCategory .

ea:OutcomeFormCategory a owl:Class ;
  owl:disjointUnionOf ( ea:ProductOutcome ea:LivePerformanceOutcome ) ;
  rdfs:comment "Performance formats are further classified into products and performances." .

ea:ProductOutcome a owl:Class ; rdfs:subClassOf ea:OutcomeFormCategory .
ea:LivePerformanceOutcome a owl:Class ; rdfs:subClassOf ea:OutcomeFormCategory .

ea:ProductBasedAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:PerformanceAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasOutcomeForm ; owl:someValuesFrom ea:ProductOutcome ] ) ] ;
  rdfs:comment "Results in a product such as a painting, portfolio, paper or exhibition." .

ea:LivePerformanceAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:PerformanceAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasOutcomeForm ; owl:someValuesFrom ea:LivePerformanceOutcome ] ) ] ;
  rdfs:comment "Consists of a performance such as a speech, athletic skill, musical recital, or reading." .

#################################################################
# PORTFOLIO / CONTINUOUS / COMPETENCY-BASED
#################################################################

ea:Portfolio a owl:Class ;
  skos:altLabel "e-portfolio", "digital portfolio", "student portfolio" ;
  rdfs:comment "A compilation of academic work and other educational evidence." .

ea:PortfolioBasedAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment .

ea:hasPortfolio a owl:ObjectProperty ;
  rdfs:domain ea:PortfolioBasedAssessment ;
  rdfs:range ea:Portfolio .

ea:ContinuousAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Evaluates a student's progress throughout a prescribed course; often includes formative assessment; an alternative to the final-examination system." .

ea:CompetencyBasedLearning a owl:Class ;
  skos:altLabel "proficiency-based learning", "mastery-based learning", "outcome-based learning", "performance-based learning", "standards-based learning" ;
  rdfs:comment "Systems of instruction, assessment, grading and academic reporting based on students demonstrating learned knowledge/skills." .

#################################################################
# TEST ITEM FORMAT HIERARCHY
#################################################################

ea:ChoiceItem a owl:Class ;
  rdfs:subClassOf ea:TestItem ;
  rdfs:comment "A multiple-choice-family item consisting of a stem and several alternative answers (options)." .

ea:AnswerOption a owl:Class .

ea:hasStem a owl:DatatypeProperty ;
  rdfs:domain ea:ChoiceItem ;
  rdfs:range xsd:string .

ea:hasOption a owl:ObjectProperty ;
  rdfs:domain ea:ChoiceItem ;
  rdfs:range ea:AnswerOption .

ea:hasKey a owl:ObjectProperty ;
  rdfs:subPropertyOf ea:hasOption ;
  rdfs:domain ea:ChoiceItem ;
  rdfs:range ea:AnswerOption ;
  rdfs:comment "The option(s) marked as the correct answer." .

ea:hasDistractor a owl:ObjectProperty ;
  rdfs:subPropertyOf ea:hasOption ;
  rdfs:domain ea:ChoiceItem ;
  rdfs:range ea:AnswerOption ;
  rdfs:comment "An incorrect option designed to be plausible." .

ea:MultipleChoiceItem a owl:Class ;
  rdfs:subClassOf ea:ChoiceItem ;
  owl:equivalentClass [ owl:intersectionOf ( ea:ChoiceItem ea:ObjectiveQuestion
      [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:onClass ea:AnswerOption ;
        owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ] ) ] ;
  skos:altLabel "MCQ", "objective response" ;
  rdfs:comment "Only one answer may be keyed as correct." .

ea:MultipleResponseItem a owl:Class ;
  rdfs:subClassOf ea:ChoiceItem ;
  owl:equivalentClass [ owl:intersectionOf ( ea:ChoiceItem ea:ObjectiveQuestion
      [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:onClass ea:AnswerOption ;
        owl:minQualifiedCardinality "2"^^xsd:nonNegativeInteger ] ) ] ;
  rdfs:comment "More than one answer may be keyed as correct, contrasting with multiple-choice items." .

ea:OneBestAnswerItem a owl:Class ;
  rdfs:subClassOf ea:MultipleChoiceItem ;
  rdfs:comment "One of 'two families of multiple-choice questions' described in the corpus (One-Best-Answer vs. a True/False family requiring selection of all appropriate answers). NOTE: this second classification of multiple-choice families overlaps terminologically with the separate MultipleChoiceItem/MultipleResponseItem and TrueFalseItem classes; both schemes are preserved." .

ea:TrueFalseItem a owl:Class ;
  rdfs:subClassOf ea:ObjectiveQuestion .

ea:MatchingItem a owl:Class ;
  rdfs:subClassOf ea:ObjectiveQuestion .

ea:EssayItem a owl:Class ;
  rdfs:subClassOf ea:SubjectiveQuestion ;
  skos:altLabel "essay question" .

ea:ExtendedResponseItem a owl:Class ;
  rdfs:subClassOf ea:SubjectiveQuestion .

ea:FreeResponseQuestion a owl:Class ;
  rdfs:subClassOf ea:SubjectiveQuestion ;
  skos:altLabel "FRQ" ;
  rdfs:comment "An open-ended question requiring a prose response, graded also for persuasiveness, style and mastery." .

ea:FillInTheBlankItem a owl:Class ;
  rdfs:subClassOf ea:TestItem ;
  rdfs:comment "Requires the test taker to recall a correct term; may or may not provide a word bank." .

ea:ShortAnswerItem a owl:Class ;
  rdfs:subClassOf ea:TestItem .

owl:AllDisjointClasses [ owl:members ( ea:TrueFalseItem ea:MultipleChoiceItem ea:MultipleResponseItem
                                        ea:MatchingItem ea:EssayItem ea:ExtendedResponseItem
                                        ea:FreeResponseQuestion ea:FillInTheBlankItem ea:ShortAnswerItem ) ] .

ea:hasItem a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:TestItem .

ea:isItemOf a owl:ObjectProperty ;
  owl:inverseOf ea:hasItem ;
  rdfs:domain ea:TestItem ;
  rdfs:range ea:Assessment .

ea:hasItemCount a owl:DatatypeProperty ;
  rdfs:domain ea:Test ;
  rdfs:range xsd:integer .

#################################################################
# SPECIFIC TESTS
#################################################################

ea:Quiz a owl:Class ; rdfs:subClassOf ea:Test ;
  rdfs:comment "A brief assessment, usually provided as a formative assessment." .
ea:MidtermExamination a owl:Class ; rdfs:subClassOf ea:Test ;
  rdfs:comment "Given near the middle of an academic term; a type of formative or summative assessment." .
ea:FinalExamination a owl:Class ; rdfs:subClassOf ea:Test ;
  rdfs:comment "A final review and assessment of topics covered; typically summative." .

#################################################################
# VALIDITY HIERARCHY
#################################################################

ea:Validity a owl:Class ;
  rdfs:comment "The degree to which an assessment measures what it is supposed to measure." .

ea:hasValidityCoefficient a owl:DatatypeProperty ;
  rdfs:domain ea:Validity ;
  rdfs:range xsd:decimal .

ea:ContentValidity a owl:Class ; rdfs:subClassOf ea:Validity ; skos:altLabel "logical validity" .
ea:CriterionValidity a owl:Class ; rdfs:subClassOf ea:Validity ; skos:altLabel "criterion-related validity" .
ea:ConstructValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:FaceValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:ConsequentialValidity a owl:Class ; rdfs:subClassOf ea:Validity .

ea:ConcurrentValidity a owl:Class ; rdfs:subClassOf ea:CriterionValidity ;
  rdfs:comment "Test data and criterion data are collected at the same time." .
ea:PredictiveValidity a owl:Class ; rdfs:subClassOf ea:CriterionValidity ;
  rdfs:comment "Test data collected first, used to predict criterion data collected later." .

ea:ConvergentValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity .
ea:DiscriminantValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity .

owl:AllDisjointClasses [ owl:members ( ea:ContentValidity ea:CriterionValidity ea:ConstructValidity
                                        ea:FaceValidity ea:ConsequentialValidity ) ] .

ea:ContentValidity rdfs:subClassOf ea:ConstructValidity .
ea:CriterionValidity rdfs:subClassOf ea:ConstructValidity .

ea:ConstructValidity rdfs:comment "TENSION: one passage lists content, criterion and construct validity as coordinate categories of evidence (modeled above as pairwise disjoint siblings of Validity), while another passage states construct validity 'subsumes all other types of validity... such as content validity and criterion validity', modeled here as additional rdfs:subClassOf axioms placing ContentValidity and CriterionValidity under ConstructValidity. Both the disjointness and the subsumption axioms are retained." .

#################################################################
# RELIABILITY HIERARCHY (two independent classification axes)
#################################################################

ea:Reliability a owl:Class ;
  rdfs:comment "The consistency of an assessment. TENSION: the corpus offers two distinct classification schemes both called 'types of reliability' -- (1) by estimation method: inter-rater, test-retest, inter-method, internal consistency; (2) by error source: student-related, rater-related, test-administration-related, test-related. Both are modeled below." .

ea:hasReliabilityCoefficient a owl:DatatypeProperty ;
  rdfs:domain ea:Reliability ;
  rdfs:range xsd:decimal .

# Axis A: by estimation method
ea:InterRaterReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  skos:altLabel "inter-rater agreement", "inter-observer reliability" .
ea:TestRetestReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  skos:altLabel "repeatability" .
ea:InterMethodReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  skos:altLabel "parallel-forms reliability", "alternate-forms reliability" .
ea:InternalConsistencyReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:SplitHalfReliability a owl:Class ; rdfs:subClassOf ea:InterMethodReliability ;
  rdfs:comment "Treats the two halves of a measure as alternate forms." .

owl:AllDisjointClasses [ owl:members ( ea:InterRaterReliability ea:TestRetestReliability
                                        ea:InterMethodReliability ea:InternalConsistencyReliability ) ] .

# Axis B: by error source
ea:hasErrorSource a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Reliability ;
  rdfs:range ea:ErrorSourceCategory .

ea:ErrorSourceCategory a owl:Class ;
  owl:disjointUnionOf ( ea:StudentRelatedSource ea:RaterRelatedSource
                         ea:TestAdministrationRelatedSource ea:TestRelatedSource ) .

ea:StudentRelatedSource a owl:Class ; rdfs:subClassOf ea:ErrorSourceCategory .
ea:RaterRelatedSource a owl:Class ; rdfs:subClassOf ea:ErrorSourceCategory .
ea:TestAdministrationRelatedSource a owl:Class ; rdfs:subClassOf ea:ErrorSourceCategory .
ea:TestRelatedSource a owl:Class ; rdfs:subClassOf ea:ErrorSourceCategory .

ea:StudentRelatedReliability a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Reliability
      [ a owl:Restriction ; owl:onProperty ea:hasErrorSource ; owl:someValuesFrom ea:StudentRelatedSource ] ) ] .
ea:RaterRelatedReliability a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Reliability
      [ a owl:Restriction ; owl:onProperty ea:hasErrorSource ; owl:someValuesFrom ea:RaterRelatedSource ] ) ] .
ea:TestAdministrationRelatedReliability a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Reliability
      [ a owl:Restriction ; owl:onProperty ea:hasErrorSource ; owl:someValuesFrom ea:TestAdministrationRelatedSource ] ) ] .
ea:TestRelatedReliability a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Reliability
      [ a owl:Restriction ; owl:onProperty ea:hasErrorSource ; owl:someValuesFrom ea:TestRelatedSource ] ) ] .

#################################################################
# RUBRIC HIERARCHY
#################################################################

ea:Rubric a owl:Class ;
  rdfs:comment "A scoring guide used to evaluate the quality of students' constructed responses." .

ea:hasRubric a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:Rubric .

ea:hasRubricType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Rubric ;
  rdfs:range ea:RubricTypeCategory .

ea:RubricTypeCategory a owl:Class ;
  owl:disjointUnionOf ( ea:HolisticRubricType ea:AnalyticRubricType ea:DevelopmentalRubricType ) ;
  rdfs:comment "Rubrics can be classified as holistic, analytic, or developmental." .

ea:HolisticRubricType a owl:Class ; rdfs:subClassOf ea:RubricTypeCategory .
ea:AnalyticRubricType a owl:Class ; rdfs:subClassOf ea:RubricTypeCategory .
ea:DevelopmentalRubricType a owl:Class ; rdfs:subClassOf ea:RubricTypeCategory .

ea:HolisticRubric a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Rubric
      [ a owl:Restriction ; owl:onProperty ea:hasRubricType ; owl:someValuesFrom ea:HolisticRubricType ] ) ] ;
  rdfs:comment "Provides an overall rating for a piece of work, considering all aspects." .

ea:AnalyticRubric a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Rubric
      [ a owl:Restriction ; owl:onProperty ea:hasRubricType ; owl:someValuesFrom ea:AnalyticRubricType ] ) ] ;
  rdfs:comment "Evaluates various dimensions or components separately." .

ea:DevelopmentalRubric a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Rubric
      [ a owl:Restriction ; owl:onProperty ea:hasRubricType ; owl:someValuesFrom ea:DevelopmentalRubricType ] ) ] ;
  rdfs:subClassOf ea:AnalyticRubric ;
  rdfs:comment "TENSION: listed as a third coordinate rubric category alongside holistic and analytic (hence included in the disjoint value-partition above), yet also explicitly described as 'a subset of analytical rubrics' (hence rdfs:subClassOf ea:AnalyticRubric here). Both axioms are retained." .

#################################################################
# GRADING / SCORING APPROACH
#################################################################

ea:GradingApproach a owl:Class ;
  rdfs:comment "An approach to scoring/grading student work." .

ea:hasGradingApproach a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:GradingApproach .

ea:HolisticGrading a owl:Class ;
  rdfs:subClassOf ea:GradingApproach ;
  skos:altLabel "holistic scoring", "nonreductionist grading" ;
  rdfs:comment "Bases a grade on a paper's overall quality, treating the composition as a whole." .

ea:AnalyticGrading a owl:Class ;
  rdfs:subClassOf ea:GradingApproach ;
  skos:altLabel "analytic scoring" ;
  rdfs:comment "Takes more factors into account, judging criterion-by-criterion." .

ea:HolisticGrading owl:disjointWith ea:AnalyticGrading .

ea:TraitInformedScoring a owl:Class ;
  rdfs:subClassOf ea:GradingApproach ;
  rdfs:comment "Trains raters to score against a rubric with several criteria; 'comes close to analytic scoring methods' yet 'remains holistic at heart' -- the corpus itself treats it as straddling both holistic and analytic grading." .

#################################################################
# LEARNING OUTCOMES
#################################################################

ea:LearningOutcome a owl:Class ;
  rdfs:comment "A statement about what students should be able to do by the end of a teaching session." .

ea:hasLearningOutcome a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:LearningOutcome .

ea:IntendedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ;
  rdfs:comment "Equated to 'aims' of a course." .
ea:MeasuredLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ;
  rdfs:comment "Equated to 'objectives' of a course." .
ea:UnintendedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ;
  rdfs:comment "Beneficial outcomes neither planned nor sought but observed." .

owl:AllDisjointClasses [ owl:members ( ea:IntendedLearningOutcome ea:MeasuredLearningOutcome
                                        ea:UnintendedLearningOutcome ) ] .

#################################################################
# TRANSFER OF LEARNING
#################################################################

ea:TransferOfLearning a owl:Class ;
  rdfs:comment "The application of skill, knowledge or understanding to resolve a novel problem or situation." .

ea:hasTransferDistance a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:TransferOfLearning ;
  rdfs:range ea:TransferDistanceCategory .

ea:TransferDistanceCategory a owl:Class ;
  owl:disjointUnionOf ( ea:NearTransferDistance ea:FarTransferDistance ) .

ea:NearTransferDistance a owl:Class ; rdfs:subClassOf ea:TransferDistanceCategory .
ea:FarTransferDistance a owl:Class ; rdfs:subClassOf ea:TransferDistanceCategory .

ea:NearTransfer a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TransferOfLearning
      [ a owl:Restriction ; owl:onProperty ea:hasTransferDistance ; owl:someValuesFrom ea:NearTransferDistance ] ) ] ;
  rdfs:comment "Application of skill to solve a novel problem in a similar context." .

ea:FarTransfer a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TransferOfLearning
      [ a owl:Restriction ; owl:onProperty ea:hasTransferDistance ; owl:someValuesFrom ea:FarTransferDistance ] ) ] ;
  rdfs:comment "Application of skill to solve a novel problem in a different context." .

ea:hasTransferValence a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:TransferOfLearning ;
  rdfs:range ea:TransferValenceCategory .

ea:TransferValenceCategory a owl:Class ;
  owl:disjointUnionOf ( ea:PositiveTransferValence ea:NegativeTransferValence ) .

ea:PositiveTransferValence a owl:Class ; rdfs:subClassOf ea:TransferValenceCategory .
ea:NegativeTransferValence a owl:Class ; rdfs:subClassOf ea:TransferValenceCategory .

ea:PositiveTransfer a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TransferOfLearning
      [ a owl:Restriction ; owl:onProperty ea:hasTransferValence ; owl:someValuesFrom ea:PositiveTransferValence ] ) ] .

ea:NegativeTransfer a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TransferOfLearning
      [ a owl:Restriction ; owl:onProperty ea:hasTransferValence ; owl:someValuesFrom ea:NegativeTransferValence ] ) ] .

#################################################################
# LEARNING FORMALITY (distinct from Assessment formality)
#################################################################

ea:Learning a owl:Class .

ea:FormalLearning a owl:Class ; rdfs:subClassOf ea:Learning .
ea:NonFormalLearning a owl:Class ; rdfs:subClassOf ea:Learning ;
  rdfs:comment "Organized learning outside the formal learning system." .
ea:InformalLearning a owl:Class ; rdfs:subClassOf ea:Learning ;
  rdfs:comment "Less structured than non-formal learning; occurs through day-to-day experience." .

owl:AllDisjointClasses [ owl:members ( ea:FormalLearning ea:NonFormalLearning ea:InformalLearning ) ] .

#################################################################
# RELATED PHENOMENA (lightly modeled, not axis-reified)
#################################################################

ea:MeasurementError a owl:Class ;
  rdfs:comment "The difference between what a test score indicates and a student's actual knowledge/abilities, or errors introduced in data collection/calculation." .

ea:ScoreInflation a owl:Class ;
  rdfs:comment "Student scores increase without genuine improvement in learning." .

ea:ValueAddedMeasure a owl:Class ;
  skos:altLabel "growth measure" ;
  rdfs:comment "Statistical estimate of a teacher's effect on student learning during a school year." .

ea:TestAnxiety a owl:Class ;
  rdfs:comment "Anxiety experienced by a test taker who believes they are being judged and may receive an unfavorable evaluation." .

ea:TeachingToTheTest a owl:Class ;
  rdfs:comment "Deliberately narrowing instruction to focus only on material that will be measured on a test." .

ea:Cheating a owl:Class ;
  rdfs:comment "Using unauthorized means or methods to obtain a desired test score or grade." .

ea:ConstructiveAlignment a owl:Class ;
  rdfs:comment "Principle for devising teaching, learning and assessment tasks that directly address intended learning outcomes." .

ea:CorrectiveFeedback a owl:Class ;
  rdfs:comment "Formal or informal feedback given to a learner on understanding or performance; must be nonevaluative, supportive, timely and specific." .
