```turtle
@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

<http://example.org/onto/assessment>
  a owl:Ontology ;
  rdfs:comment "Ontology of educational assessment, test, validity, reliability, rubric, feedback and related concepts, modeling classification claims from the corpus, including explicitly conflicting/overlapping classifications noted as comments." .

#################################################################
# ROOT
#################################################################

ea:EducationalConstruct a owl:Class ;
  rdfs:label "EducationalConstruct" .

#################################################################
# ASSESSMENT / TEST CORE
#################################################################

ea:Assessment a owl:Class ;
  rdfs:subClassOf ea:EducationalConstruct ;
  skos:altLabel "educational evaluation", "evaluation" ;
  rdfs:comment "Systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve learning. NOTE: the corpus also uses 'evaluation' as a synonym of 'examination/test' in a separate passage, creating a terminological tension between 'evaluation = assessment' (top-level) and 'evaluation = exam/test' (examination passage)." .

ea:Test a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "exam", "examination" ;
  rdfs:comment "Assessment is often used interchangeably with test but is not limited to tests; a test is an educational assessment intended to measure knowledge, skill, aptitude, physical fitness, or classification." .

ea:AssessmentItem a owl:Class ;
  rdfs:subClassOf ea:EducationalConstruct ;
  rdfs:comment "An item ('question') belonging to a test; the general term preferred over 'question' because many items are not phrased as questions." .

ea:hasItem a owl:ObjectProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:AssessmentItem .

ea:isItemOf a owl:ObjectProperty ;
  owl:inverseOf ea:hasItem ;
  rdfs:domain ea:AssessmentItem ;
  rdfs:range ea:Test .

ea:Examiner a owl:Class ; rdfs:subClassOf ea:EducationalConstruct .
ea:ExpertExaminer a owl:Class ; rdfs:subClassOf ea:Examiner .

ea:hasExaminer a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:Examiner .

#################################################################
# AXIS 1: PURPOSE / TIMING (placement, formative, summative, diagnostic)
#################################################################

ea:hasPurpose a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:PurposeCategory .

ea:PurposeCategory a owl:Class ;
  owl:disjointUnionOf ( ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose ) .

ea:PlacementPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:FormativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:SummativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:DiagnosticPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .

ea:PlacementAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "pre-assessment", "initial assessment", "threshold knowledge test", "TKT" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ] ) ] .

ea:FormativeAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "educative assessment", "classroom assessment", "assessment for learning" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ] ) ] .

ea:SummativeAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "assessment of learning" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ] ) ] .

ea:DiagnosticAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ] ) ] ;
  rdfs:subClassOf ea:FormativeAssessment ;
  rdfs:comment "TENSION: one passage lists diagnostic assessment as the 4th coordinate category alongside placement/formative/summative (numbered (1)-(4)), and asserts the three are divided into initial/formative/summative; another passage states 'A common form of formative assessment is diagnostic assessment', i.e. subordinates Diagnostic under Formative. Both the coordinate disjointness and the subClassOf axiom are encoded, producing a deliberate unsatisfiability under strict disjointness below." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:PlacementAssessment ea:FormativeAssessment ea:SummativeAssessment ea:DiagnosticAssessment ) .

ea:SelfAssessment a owl:Class ;
  rdfs:subClassOf ea:DiagnosticAssessment ;
  rdfs:comment "Self-assessment is a form of diagnostic assessment in which students assess themselves." ;
  owl:equivalentClass [ owl:intersectionOf ( ea:DiagnosticAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasAssessorType ; owl:someValuesFrom ea:SelfAssessorRole ] ) ] .

ea:PeerAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasAssessorType ; owl:someValuesFrom ea:PeerAssessorRole ] ) ] .

ea:hasAssessorType a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:AssessorCategory .

ea:AssessorCategory a owl:Class ;
  owl:disjointUnionOf ( ea:TeacherAssessorRole ea:PeerAssessorRole ea:SelfAssessorRole ) .

ea:TeacherAssessorRole a owl:Class ; rdfs:subClassOf ea:AssessorCategory .
ea:PeerAssessorRole a owl:Class ; rdfs:subClassOf ea:AssessorCategory .
ea:SelfAssessorRole a owl:Class ; rdfs:subClassOf ea:AssessorCategory .

ea:ForwardLookingAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Forward-looking assessment asks those being assessed to consider themselves in hypothetical future situations." ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasTemporalOrientation ; owl:someValuesFrom ea:ForwardLookingOrientation ] ) ] .

#################################################################
# AXIS 2: ANSWER DETERMINACY (objective / subjective)
#################################################################

ea:hasAnswerDeterminacy a owl:ObjectProperty ;
  rdfs:domain ea:EducationalConstruct ;
  rdfs:range ea:AnswerDeterminacyCategory ;
  rdfs:comment "Applies both to Assessment ('objective/subjective assessment') and to AssessmentItem ('objective/subjective question types')." .

ea:AnswerDeterminacyCategory a owl:Class ;
  owl:disjointUnionOf ( ea:SingleCorrectAnswerDeterminacy ea:MultipleCorrectAnswerDeterminacy ) .

ea:SingleCorrectAnswerDeterminacy a owl:Class ; rdfs:subClassOf ea:AnswerDeterminacyCategory .
ea:MultipleCorrectAnswerDeterminacy a owl:Class ; rdfs:subClassOf ea:AnswerDeterminacyCategory .

ea:ObjectiveAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasAnswerDeterminacy ; owl:someValuesFrom ea:SingleCorrectAnswerDeterminacy ] ) ] .

ea:SubjectiveAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasAnswerDeterminacy ; owl:someValuesFrom ea:MultipleCorrectAnswerDeterminacy ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( ea:ObjectiveAssessment ea:SubjectiveAssessment ) .

ea:ObjectiveItem a owl:Class ;
  rdfs:subClassOf ea:AssessmentItem ;
  owl:equivalentClass [ owl:intersectionOf ( ea:AssessmentItem
      [ a owl:Restriction ; owl:onProperty ea:hasAnswerDeterminacy ; owl:someValuesFrom ea:SingleCorrectAnswerDeterminacy ] ) ] .

ea:SubjectiveItem a owl:Class ;
  rdfs:subClassOf ea:AssessmentItem ;
  owl:equivalentClass [ owl:intersectionOf ( ea:AssessmentItem
      [ a owl:Restriction ; owl:onProperty ea:hasAnswerDeterminacy ; owl:someValuesFrom ea:MultipleCorrectAnswerDeterminacy ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( ea:ObjectiveItem ea:SubjectiveItem ) .

ea:AnswerOption a owl:Class ; rdfs:subClassOf ea:EducationalConstruct .
ea:Key a owl:Class ; rdfs:subClassOf ea:AnswerOption .
ea:Distractor a owl:Class ; rdfs:subClassOf ea:AnswerOption .
[] a owl:AllDisjointClasses ; owl:members ( ea:Key ea:Distractor ) .

ea:hasOption a owl:ObjectProperty ;
  rdfs:domain ea:AssessmentItem ;
  rdfs:range ea:AnswerOption .

ea:isOptionOf a owl:ObjectProperty ;
  owl:inverseOf ea:hasOption ;
  rdfs:domain ea:AnswerOption ;
  rdfs:range ea:AssessmentItem .

ea:hasStem a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:MultipleChoiceItem ;
  rdfs:range xsd:string .

ea:TrueFalseItem a owl:Class ;
  rdfs:subClassOf ea:ObjectiveItem, ea:MultipleChoiceItem ;
  rdfs:comment "TENSION: one passage lists true/false as a sibling objective question type alongside multiple-choice; another passage says 'the first family [of multiple-choice questions] is known as the True/False question', i.e. subordinates it under multiple-choice. Modeled as subClassOf both to retain both framings." .

ea:MultipleChoiceItem a owl:Class ;
  rdfs:subClassOf ea:ObjectiveItem ;
  skos:altLabel "MCQ", "multiple choice question" ;
  rdfs:subClassOf [ a owl:Restriction ; owl:onProperty ea:hasOption ; owl:onClass ea:Key ; owl:qualifiedCardinality "1"^^xsd:integer ] ;
  rdfs:comment "Only one answer may be keyed as correct." .

ea:OneBestAnswerItem a owl:Class ; rdfs:subClassOf ea:MultipleChoiceItem .
[] a owl:AllDisjointClasses ; owl:members ( ea:TrueFalseItem ea:OneBestAnswerItem ) .

ea:MultipleResponseItem a owl:Class ;
  rdfs:subClassOf ea:ObjectiveItem ;
  rdfs:subClassOf [ a owl:Restriction ; owl:onProperty ea:hasOption ; owl:onClass ea:Key ; owl:minQualifiedCardinality "2"^^xsd:integer ] ;
  rdfs:comment "More than one answer may be keyed as correct; contrasted explicitly with MultipleChoiceItem." .

ea:MatchingItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .

[] a owl:AllDisjointClasses ; owl:members ( ea:MultipleChoiceItem ea:MultipleResponseItem ea:MatchingItem ea:TrueFalseItem ) .

ea:FillInTheBlankItem a owl:Class ;
  rdfs:subClassOf ea:ObjectiveItem ;
  rdfs:comment "Requires the test taker to recall the correct term to fill an identified blank." .

ea:WordBankFillInTheBlankItem a owl:Class ; rdfs:subClassOf ea:FillInTheBlankItem .
ea:OpenFillInTheBlankItem a owl:Class ; rdfs:subClassOf ea:FillInTheBlankItem .
[] a owl:AllDisjointClasses ; owl:members ( ea:WordBankFillInTheBlankItem ea:OpenFillInTheBlankItem ) .

ea:ExtendedResponseItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem .
ea:EssayItem a owl:Class ;
  rdfs:subClassOf ea:SubjectiveItem ;
  skos:altLabel "free response question", "FRQ", "essay question" .
ea:ShortAnswerItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem .

[] a owl:AllDisjointClasses ; owl:members ( ea:ExtendedResponseItem ea:EssayItem ea:ShortAnswerItem ) .

ea:MathItem a owl:Class ;
  rdfs:subClassOf ea:AssessmentItem ;
  rdfs:comment "Corpus states most mathematics/calculation questions 'employ a style which does not fall into any of the above categories', i.e. explicitly neither ObjectiveItem nor SubjectiveItem; therefore no hasAnswerDeterminacy bridging is asserted for this class." .

#################################################################
# AXIS 3: REFERENCING (criterion / norm / ipsative) & SCORE INTERPRETATION
#################################################################

ea:hasReferencing a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:ReferencingCategory .

ea:ReferencingCategory a owl:Class ;
  owl:disjointUnionOf ( ea:CriterionReferencing ea:NormReferencing ea:IpsativeReferencing ) .

ea:CriterionReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:NormReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:IpsativeReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .

ea:CriterionReferencedAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment, ea:Test ;
  skos:altLabel "CRT", "criterion-referenced test", "standards-based assessment", "standards-referenced assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencing ] ) ] .

ea:NormReferencedAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment, ea:Test ;
  skos:altLabel "NRT", "norm-referenced test", "normative assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencing ] ) ] .

ea:IpsativeAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:IpsativeReferencing ] ) ] .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:CriterionReferencedAssessment ea:NormReferencedAssessment ea:IpsativeAssessment ) ;
  rdfs:comment "TENSION: corpus elsewhere states 'there are two types of test score interpretations: norm-referenced ... or criterion-referenced', omitting ipsative from that dichotomy, while other passages explicitly contrast all three ('Ipsative assessment can be contrasted with criterion-referenced assessment and norm-referenced assessment'). Both the three-way partition (here) and the two-way ScoreInterpretation partition (below) are encoded." .

ea:MasteryTest a owl:Class ;
  rdfs:subClassOf ea:CriterionReferencedAssessment, ea:Test ;
  owl:equivalentClass [ owl:intersectionOf ( ea:CriterionReferencedAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasCutScore ; owl:someValuesFrom xsd:decimal ] ) ] .

ea:hasCutScore a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:CriterionReferencedAssessment ;
  rdfs:range xsd:decimal .

ea:ScoreInterpretation a owl:Class ; rdfs:subClassOf ea:EducationalConstruct .

ea:NormReferencedScoreInterpretation a owl:Class ;
  rdfs:subClassOf ea:ScoreInterpretation ;
  owl:equivalentClass [ owl:intersectionOf ( ea:ScoreInterpretation
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencing ] ) ] .

ea:CriterionReferencedScoreInterpretation a owl:Class ;
  rdfs:subClassOf ea:ScoreInterpretation ;
  owl:equivalentClass [ owl:intersectionOf ( ea:ScoreInterpretation
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencing ] ) ] .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:NormReferencedScoreInterpretation ea:CriterionReferencedScoreInterpretation ) .

ea:hasScoreInterpretation a owl:ObjectProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:ScoreInterpretation .

ea:CompetitiveExamination a owl:Class ;
  rdfs:subClassOf ea:Test ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencing ]
      [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:HighStakesCondition ] ) ] ;
  rdfs:comment "Competitive exams are norm-referenced, high-stakes tests in which candidates are ranked." .

#################################################################
# AXIS 4: FORMALITY (formal / informal)
#################################################################

ea:hasFormality a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:FormalityCategory .

ea:FormalityCategory a owl:Class ;
  owl:disjointUnionOf ( ea:FormalCondition ea:InformalCondition ) .

ea:FormalCondition a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:InformalCondition a owl:Class ; rdfs:subClassOf ea:FormalityCategory .

ea:FormalAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:FormalCondition ] ) ] .

ea:InformalAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:InformalCondition ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( ea:FormalAssessment ea:InformalAssessment ) .

#################################################################
# AXIS 5: LOCUS (internal / external)
#################################################################

ea:hasLocus a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:LocusCategory .

ea:LocusCategory a owl:Class ;
  owl:disjointUnionOf ( ea:InternalLocus ea:ExternalLocus ) .

ea:InternalLocus a owl:Class ; rdfs:subClassOf ea:LocusCategory .
ea:ExternalLocus a owl:Class ; rdfs:subClassOf ea:LocusCategory .

ea:InternalAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasLocus ; owl:someValuesFrom ea:InternalLocus ] ) ] .

ea:ExternalAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasLocus ; owl:someValuesFrom ea:ExternalLocus ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( ea:InternalAssessment ea:ExternalAssessment ) .

#################################################################
# AXIS 6: STANDARDIZATION (standardized / non-standardized)
#################################################################

ea:hasStandardization a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:StandardizationCategory .

ea:StandardizationCategory a owl:Class ;
  owl:disjointUnionOf ( ea:StandardizedCondition ea:NonStandardizedCondition ) .

ea:StandardizedCondition a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:NonStandardizedCondition a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .

ea:StandardizedTest a owl:Class ;
  rdfs:subClassOf ea:Test ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:StandardizedCondition ] ) ] .

ea:NonStandardizedTest a owl:Class ;
  rdfs:subClassOf ea:Test ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:NonStandardizedCondition ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( ea:StandardizedTest ea:NonStandardizedTest ) .

ea:AchievementTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
  owl:equivalentClass [ owl:intersectionOf ( ea:StandardizedTest
      [ a owl:Restriction ; owl:onProperty ea:hasTemporalOrientation ; owl:someValuesFrom ea:BackwardLookingOrientation ] ) ] .

ea:AptitudeTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
  owl:equivalentClass [ owl:intersectionOf ( ea:StandardizedTest
      [ a owl:Restriction ; owl:onProperty ea:hasTemporalOrientation ; owl:someValuesFrom ea:ForwardLookingOrientation ] ) ] .

ea:CollegeAdmissionsTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:InternationalComparisonTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:PsychologicalTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:AchievementTest ea:AptitudeTest ea:CollegeAdmissionsTest ea:InternationalComparisonTest ea:PsychologicalTest ) .

#################################################################
# AXIS 7: STAKES (high-stakes / low-stakes)
#################################################################

ea:hasStakes a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:StakesCategory ;
  rdfs:comment "What distinguishes a high-stakes test from a low-stakes test is not its form but its function (how results are used)." .

ea:StakesCategory a owl:Class ;
  owl:disjointUnionOf ( ea:HighStakesCondition ea:LowStakesCondition ) .

ea:HighStakesCondition a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:LowStakesCondition a owl:Class ; rdfs:subClassOf ea:StakesCategory .

ea:HighStakesTest a owl:Class ;
  rdfs:subClassOf ea:Test ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:HighStakesCondition ] ) ] .

ea:LowStakesTest a owl:Class ;
  rdfs:subClassOf ea:Test ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:LowStakesCondition ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( ea:HighStakesTest ea:LowStakesTest ) .

#################################################################
# AXIS 8: TEMPORAL ORIENTATION (backward-looking / forward-looking)
#################################################################

ea:hasTemporalOrientation a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:TemporalOrientationCategory .

ea:TemporalOrientationCategory a owl:Class ;
  owl:disjointUnionOf ( ea:BackwardLookingOrientation ea:ForwardLookingOrientation ) .

ea:BackwardLookingOrientation a owl:Class ; rdfs:subClassOf ea:TemporalOrientationCategory .
ea:ForwardLookingOrientation a owl:Class ; rdfs:subClassOf ea:TemporalOrientationCategory .

#################################################################
# AXIS 9: GRANULARITY
#################################################################

ea:hasGranularity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:GranularityCategory ;
  rdfs:comment "Assessment can focus on the individual learner, the learning community, a course, an academic program, the institution, or the educational system as a whole." .

ea:GranularityCategory a owl:Class ;
  owl:disjointUnionOf ( ea:IndividualLearnerGranularity ea:LearningCommunityGranularity ea:CourseGranularity
                        ea:AcademicProgramGranularity ea:InstitutionGranularity ea:EducationalSystemGranularity ) .

ea:IndividualLearnerGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:LearningCommunityGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:CourseGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:AcademicProgramGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:InstitutionGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:EducationalSystemGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .

#################################################################
# AXIS 10: CONTEXT (authentic / complex assessment)
#################################################################

ea:hasAssessmentContext a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:ContextCategory .

ea:ContextCategory a owl:Class ;
  owl:disjointUnionOf ( ea:RealWorldContext ea:SchoolContext ) .

ea:RealWorldContext a owl:Class ; rdfs:subClassOf ea:ContextCategory .
ea:SchoolContext a owl:Class ; rdfs:subClassOf ea:ContextCategory .

ea:AuthenticAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasAssessmentContext ; owl:someValuesFrom ea:RealWorldContext ] ) ] .

ea:Rubric a owl:Class ; rdfs:subClassOf ea:EducationalConstruct ;
  rdfs:comment "Scoring guide used to evaluate the quality of students' constructed responses." .

ea:hasRubric a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:Rubric .

ea:ComplexAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasRubric ; owl:someValuesFrom ea:Rubric ]
      [ a owl:Restriction ; owl:onProperty ea:hasExaminer ; owl:someValuesFrom ea:ExpertExaminer ] ) ] ;
  rdfs:comment "A complex assessment is the one that requires a rubric and an expert examiner (e.g. thesis, funding proposal)." .

ea:ContinuousAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "A form of educational examination that evaluates a student's progress throughout a prescribed course; often includes formative assessment as a component (overlap, not subsumption)." .

#################################################################
# PERFORMANCE-BASED ASSESSMENT / PERFORMANCE TEST / WRITTEN TEST
#################################################################

ea:PerformanceBasedAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Requires students to solve real-world problems or produce something with real-world application; described as similar to, but not formally subsumed by, summative assessment. Also sometimes called 'performance assessment' or 'authentic assessment' in the corpus (cf. ea:AuthenticAssessment)." .

ea:PerformanceOutcome a owl:Class ;
  rdfs:subClassOf ea:EducationalConstruct ;
  owl:disjointUnionOf ( ea:AcademicProduct ea:AcademicPerformance ) ;
  rdfs:comment "Performance formats are further classified into products and performances." .

ea:AcademicProduct a owl:Class ; rdfs:subClassOf ea:PerformanceOutcome .
ea:AcademicPerformance a owl:Class ; rdfs:subClassOf ea:PerformanceOutcome .

ea:hasPerformanceOutcome a owl:ObjectProperty ;
  rdfs:domain ea:PerformanceBasedAssessment ;
  rdfs:range ea:PerformanceOutcome .

ea:WrittenTest a owl:Class ;
  rdfs:subClassOf ea:Test ;
  rdfs:comment "Tests administered on paper or on a computer (eExam)." .

ea:PerformanceTest a owl:Class ;
  rdfs:subClassOf ea:Test ;
  rdfs:comment "An assessment that requires an examinee to actually perform a task or activity rather than answer questions about it, e.g. a behind-the-wheel driving test." .

[] a owl:AllDisjointClasses ; owl:members ( ea:WrittenTest ea:PerformanceTest ) .

ea:MidtermExamination a owl:Class ;
  rdfs:subClassOf ea:Test, ea:FormativeAssessment, ea:SummativeAssessment ;
  rdfs:comment "Corpus states 'Midterm exams are a type of formative or summative assessment', asserted here as subClassOf both, which conflicts with the AllDisjointClasses(Placement, Formative, Summative, Diagnostic) partition above; tension intentionally encoded." .

ea:FinalExamination a owl:Class ;
  rdfs:subClassOf ea:Test, ea:SummativeAssessment .

ea:Quiz a owl:Class ;
  rdfs:subClassOf ea:Test, ea:FormativeAssessment ;
  rdfs:comment "A brief assessment usually provided as a formative assessment, though it 'can make a significant part of the final course grade'." .

ea:InterimAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment, ea:FormativeAssessment, ea:SummativeAssessment ;
  rdfs:comment "TENSION: 'Some educators consider interim tests to be formative... but others may consider them to be summative. There is ongoing debate...'. Both subsumptions encoded, conflicting with the Formative/Summative disjointness asserted above." .

ea:ScreeningAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Used to determine whether students may need specialized services or are ready to begin a program." .

ea:CommonAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Used across a school/district for consistency; 'may be formative or summative' (non-exclusive, not modeled as disjoint subsumption)." .

ea:PortfolioBasedAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment .

ea:Portfolio a owl:Class ;
  rdfs:subClassOf ea:EducationalConstruct ;
  rdfs:comment "A compilation of academic work and other educational evidence." .

ea:PhysicalPortfolio a owl:Class ; rdfs:subClassOf ea:Portfolio .
ea:DigitalPortfolio a owl:Class ; rdfs:subClassOf ea:Portfolio ; skos:altLabel "e-portfolio" .
[] a owl:AllDisjointClasses ; owl:members ( ea:PhysicalPortfolio ea:DigitalPortfolio ) .
ea:CapstonePortfolio a owl:Class ; rdfs:subClassOf ea:Portfolio .

#################################################################
# ASSESSMENT-TYPES FLAT LIST (cross-cutting, explicitly non-disjoint)
#################################################################

ea:AssessmentTypeListing a owl:Class ;
  rdfs:subClassOf ea:EducationalConstruct ;
  rdfs:comment "The corpus enumerates 'Assessment types' as a single flat list (Formative, Summative, Norm-referenced test, Criterion-referenced test, Performance-based, Authentic, Standardized, Non-standardized, High-stakes, Competitive examinations) but explicitly clarifies 'Most tests can be classified on multiple categories... A single test can have multiple qualities' (e.g. a bar exam can be norm-referenced, standardized, AND summative at once). Therefore, unlike the strict axis-partitions above, NO disjointness is asserted across this list; the classes already declared (ea:FormativeAssessment, ea:SummativeAssessment, ea:NormReferencedAssessment, ea:CriterionReferencedAssessment, ea:PerformanceBasedAssessment, ea:AuthenticAssessment, ea:StandardizedTest, ea:NonStandardizedTest, ea:HighStakesTest, ea:CompetitiveExamination) are reused and may overlap freely." .

#################################################################
# GRADING APPROACHES & RUBRIC TYPES
#################################################################

ea:GradingApproach a owl:Class ; rdfs:subClassOf ea:EducationalConstruct .

ea:HolisticGrading a owl:Class ;
  rdfs:subClassOf ea:GradingApproach ;
  skos:altLabel "holistic scoring", "nonreductionist grading" ;
  rdfs:comment "Bases a grade on a paper's overall quality, treating the composition as a whole." .

ea:AnalyticGrading a owl:Class ;
  rdfs:subClassOf ea:GradingApproach ;
  rdfs:comment "Takes more factors into account, judging criterion by criterion." .

[] a owl:AllDisjointClasses ; owl:members ( ea:HolisticGrading ea:AnalyticGrading ) .

ea:TraitInformedScoring a owl:Class ;
  rdfs:subClassOf ea:HolisticGrading ;
  rdfs:comment "TENSION: 'Trait-informed scoring comes close to analytic scoring methods... Trait-informed holistic scoring, however, remains holistic at heart'. Modeled as subClassOf HolisticGrading per the final characterization, while noting its closeness to AnalyticGrading." .

ea:hasGradingApproach a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:GradingApproach .

ea:HolisticRubric a owl:Class ; rdfs:subClassOf ea:Rubric .
ea:AnalyticRubric a owl:Class ; rdfs:subClassOf ea:Rubric .
ea:DevelopmentalRubric a owl:Class ;
  rdfs:subClassOf ea:Rubric, ea:AnalyticRubric ;
  rdfs:comment "TENSION: 'Rubrics can be classified as holistic, analytic, or developmental' (coordinate triad, encoded via AllDisjointClasses below) vs. 'Developmental rubrics, a subset of analytical rubrics' (subordinate, encoded via subClassOf AnalyticRubric). Both are encoded, which makes ea:DevelopmentalRubric unsatisfiable under strict reasoning -- intentional per corpus conflict." .

[] a owl:AllDisjointClasses ; owl:members ( ea:HolisticRubric ea:AnalyticRubric ea:DevelopmentalRubric ) .

#################################################################
# VALIDITY
#################################################################

ea:Validity a owl:Class ; rdfs:subClassOf ea:EducationalConstruct ;
  rdfs:comment "The degree to which an assessment measures what it is supposed to measure." .

ea:hasValidity a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:Validity .

ea:hasValidityCoefficient a owl:DatatypeProperty ;
  rdfs:domain ea:Validity ;
  rdfs:range xsd:decimal .

ea:ContentValidity a owl:Class ; rdfs:subClassOf ea:Validity ; skos:altLabel "logical validity" .
ea:CriterionValidity a owl:Class ; rdfs:subClassOf ea:Validity ; skos:altLabel "criterion-related validity" .
ea:ConstructValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:ConsequentialValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:FaceValidity a owl:Class ; rdfs:subClassOf ea:Validity .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:ContentValidity ea:CriterionValidity ea:ConstructValidity ea:ConsequentialValidity ea:FaceValidity ) ;
  rdfs:comment "Validity is generally gauged through examination of evidence in these coordinate categories." .

ea:ContentValidity rdfs:subClassOf ea:ConstructValidity .
ea:CriterionValidity rdfs:subClassOf ea:ConstructValidity .
ea:FaceValidity rdfs:subClassOf ea:ConstructValidity .
# TENSION: "Construct validity ... subsumes all other types of validity" and "Modern validity theory
# defines construct validity as the overarching concern of validity research, subsuming all other
# types of validity evidence such as content validity and criterion validity." These subClassOf
# axioms directly conflict with the AllDisjointClasses partition declared immediately above,
# which is the intended, explicitly-flagged tension between the coordinate-list framing and the
# subsumption framing found in the corpus.

ea:ConcurrentValidity a owl:Class ; rdfs:subClassOf ea:CriterionValidity .
ea:PredictiveValidity a owl:Class ; rdfs:subClassOf ea:CriterionValidity .
[] a owl:AllDisjointClasses ; owl:members ( ea:ConcurrentValidity ea:PredictiveValidity ) .

ea:ConvergentValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity .
ea:DiscriminantValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity .
[] a owl:AllDisjointClasses ; owl:members ( ea:ConvergentValidity ea:DiscriminantValidity ) .

ea:ConcurrentValidity owl:disjointWith ea:ConvergentValidity ;
  rdfs:comment "Corpus explicitly: 'Concurrent validity differs from convergent validity'." .

#################################################################
# RELIABILITY
#################################################################

ea:Reliability a owl:Class ; rdfs:subClassOf ea:EducationalConstruct ;
  rdfs:comment "The consistency of an assessment; freedom of a measure from measurement error." .

ea:hasReliability a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:Reliability .

ea:hasReliabilityCoefficient a owl:DatatypeProperty ;
  rdfs:domain ea:Reliability ;
  rdfs:range xsd:decimal .

ea:ReliabilityFactor a owl:Class ;
  rdfs:subClassOf ea:EducationalConstruct ;
  owl:disjointUnionOf ( ea:StudentRelatedReliabilityFactor ea:RaterRelatedReliabilityFactor
                        ea:TestAdministrationRelatedReliabilityFactor ea:TestRelatedReliabilityFactor ) ;
  rdfs:comment "There are four types of reliability: student-related, rater-related, test administration-related, and test-related." .

ea:StudentRelatedReliabilityFactor a owl:Class ; rdfs:subClassOf ea:ReliabilityFactor .
ea:RaterRelatedReliabilityFactor a owl:Class ; rdfs:subClassOf ea:ReliabilityFactor .
ea:TestAdministrationRelatedReliabilityFactor a owl:Class ; rdfs:subClassOf ea:ReliabilityFactor .
ea:TestRelatedReliabilityFactor a owl:Class ; rdfs:subClassOf ea:ReliabilityFactor .

ea:hasReliabilityFactor a owl:ObjectProperty ;
  rdfs:domain ea:Reliability ;
  rdfs:range ea:ReliabilityFactor .

ea:ReliabilityEstimationMethod a owl:Class ;
  rdfs:subClassOf ea:Reliability ;
  owl:disjointUnionOf ( ea:InterRaterReliability ea:TestRetestReliability ea:ParallelFormsReliability ea:InternalConsistencyReliability ) ;
  rdfs:comment "Several general classes of reliability estimates." .

ea:InterRaterReliability a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimationMethod .

ea:TestRetestReliability a owl:Class ;
  rdfs:subClassOf ea:ReliabilityEstimationMethod ;
  skos:altLabel "repeatability" .

ea:IntraRaterReliability a owl:Class ; rdfs:subClassOf ea:TestRetestReliability .

ea:ParallelFormsReliability a owl:Class ;
  rdfs:subClassOf ea:ReliabilityEstimationMethod ;
  skos:altLabel "inter-method reliability", "alternate-forms reliability" .

ea:SplitHalfReliability a owl:Class ;
  rdfs:subClassOf ea:ParallelFormsReliability ;
  rdfs:comment "Treats the two halves of a measure as alternate forms." .

ea:InternalConsistencyReliability a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimationMethod .

#################################################################
# LEARNING OUTCOME
#################################################################

ea:LearningOutcome a owl:Class ; rdfs:subClassOf ea:EducationalConstruct ;
  rdfs:comment "Statements about what students should be able to do by the end of a teaching session." .

ea:hasLearningOutcome a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:LearningOutcome .

ea:AimLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ; skos:altLabel "intended learning outcome", "ILO" .
ea:ObjectiveLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ; skos:altLabel "measured learning outcome" .
ea:UnintendedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:AimLearningOutcome ea:ObjectiveLearningOutcome ea:UnintendedLearningOutcome ) .

ea:LearningOutcomeTaxonomy a owl:Class ;
  rdfs:subClassOf ea:EducationalConstruct ;
  owl:disjointUnionOf ( ea:BloomsTaxonomy ea:StructureOfObservedLearningOutcome ea:DIKWPyramid ea:ModelOfHierarchicalComplexity ) .

ea:BloomsTaxonomy a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy .
ea:StructureOfObservedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy ; skos:altLabel "SOLO" .
ea:DIKWPyramid a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy .
ea:ModelOfHierarchicalComplexity a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy .

ea:ConstructiveAlignment a owl:Class ;
  rdfs:subClassOf ea:EducationalConstruct ;
  rdfs:comment "Principle for devising teaching/learning activities and assessment tasks that directly address intended learning outcomes." .

#################################################################
# FEEDBACK
#################################################################

ea:Feedback a owl:Class ; rdfs:subClassOf ea:EducationalConstruct .

ea:hasFeedback a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:Feedback .

ea:CorrectiveFeedback a owl:Class ;
  rdfs:subClassOf ea:Feedback ;
  rdfs:comment "Must be nonevaluative, supportive, timely, and specific; contrasted with insults." .

ea:Recast a owl:Class ;
  rdfs:subClassOf ea:CorrectiveFeedback ;
  rdfs:comment "Subtle correction of a young child's spoken errors (motherese)." .

ea:ImmediateFeedbackAssessmentTechnique a owl:Class ;
  rdfs:subClassOf ea:CorrectiveFeedback ;
  skos:altLabel "IF-AT" .

ea:FormativeFeedback a owl:Class ; rdfs:subClassOf ea:Feedback .
ea:SummativeFeedback a owl:Class ; rdfs:subClassOf ea:Feedback .
[] a owl:AllDisjointClasses ; owl:members ( ea:FormativeFeedback ea:SummativeFeedback ) .

#################################################################
# LEARNING (formal / non-formal / informal) & TRANSFER
#################################################################

ea:Learning a owl:Class ; rdfs:subClassOf ea:EducationalConstruct .

ea:FormalLearning a owl:Class ; rdfs:subClassOf ea:Learning .
ea:NonFormalLearning a owl:Class ;
  rdfs:subClassOf ea:Learning ;
  rdfs:comment "Organized learning outside the formal learning system." .
ea:InformalLearning a owl:Class ;
  rdfs:subClassOf ea:Learning ;
  rdfs:comment "Less structured than non-formal learning; experience of day-to-day situations." .

[] a owl:AllDisjointClasses ; owl:members ( ea:FormalLearning ea:NonFormalLearning ea:InformalLearning ) .

ea:TransferOfLearning a owl:Class ; rdfs:subClassOf ea:EducationalConstruct .

ea:NearTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning .
ea:FarTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning .
[] a owl:AllDisjointClasses ; owl:members ( ea:NearTransfer ea:FarTransfer ) .

ea:PositiveTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning .
ea:NegativeTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning .
[] a owl:AllDisjointClasses ; owl:members ( ea:PositiveTransfer ea:NegativeTransfer ) .

#################################################################
# COMPETENCY-BASED LEARNING
#################################################################

ea:CompetencyBasedLearning a owl:Class ;
  rdfs:subClassOf ea:EducationalConstruct ;
  skos:altLabel "proficiency-based learning", "mastery-based learning", "outcome-based learning",
               "performance-based education", "standards-based education" ;
  rdfs:comment "TERMINOLOGY NOTE: the altLabel 'performance-based' here denotes an instructional/grading system synonym set, distinct from ea:PerformanceBasedAssessment (a kind of Assessment); the corpus uses 'performance-based' for both, a terminological overlap worth flagging." .

#################################################################
# PROFICIENCY / MEASUREMENT ERROR / VALUE-ADDED / SCORE INFLATION
#################################################################

ea:Proficiency a owl:Class ; rdfs:subClassOf ea:EducationalConstruct .
ea:ProficiencyLevel a owl:Class ; rdfs:subClassOf ea:EducationalConstruct .

ea:MeasurementError a owl:Class ;
  rdfs:subClassOf ea:EducationalConstruct ;
  owl:disjointUnionOf ( ea:TestScoreMeasurementError ea:DataReportingMeasurementError ) ;
  rdfs:comment "Measurement error refers to either (1) the difference between a test score and actual knowledge, or (2) errors introduced when collecting and calculating data-based reports." .

ea:TestScoreMeasurementError a owl:Class ; rdfs:subClassOf ea:MeasurementError .
ea:DataReportingMeasurementError a owl:Class ; rdfs:subClassOf ea:MeasurementError .

ea:ScoreInflation a owl:Class ;
  rdfs:subClassOf ea:EducationalConstruct ;
  rdfs:comment "Student scores increase without genuine learning improvement." .

ea:TeacherEvaluationMeasure a owl:Class ; rdfs:subClassOf ea:EducationalConstruct .

ea:ValueAddedMeasure a owl:Class ;
  rdfs:subClassOf ea:TeacherEvaluationMeasure ;
  skos:altLabel "growth measure" ;
  rdfs:comment "TENSION: first introduced as 'Value-added measures, or growth measures' (synonyms), but later the corpus states 'Student growth measures are a related—but distinct—method'. Both the synonym altLabel and the distinct sibling class ea:StudentGrowthMeasure are encoded." .

ea:StudentGrowthMeasure a owl:Class ;
  rdfs:subClassOf ea:TeacherEvaluationMeasure .

ea:hasItemCount a owl:DatatypeProperty ;
  rdfs:domain ea:Test ;
  rdfs:range xsd:integer .

#################################################################
# TEST STAKES-RELATED GENUS/DIFFERENTIA ALREADY COVERED ABOVE
#################################################################
